begin;
create extension if not exists pg_jsonschema with schema extensions;
create table public.curriculum_editors (
 user_id uuid primary key references auth.users(id) on delete cascade,
 created_at timestamptz not null default now()
);
alter table public.curriculum_editors enable row level security;
create policy own_editor_role on public.curriculum_editors for select to authenticated using (user_id=(select auth.uid()));
revoke all on public.curriculum_editors from anon,authenticated;
grant select on public.curriculum_editors to authenticated;
create function public.is_curriculum_editor() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.curriculum_editors where user_id=auth.uid());
$$;
revoke all on function public.is_curriculum_editor() from public,anon;
grant execute on function public.is_curriculum_editor() to authenticated;
create table public.curriculum_releases (
 version integer primary key check(version>=2),
 title text not null check(length(title) between 1 and 200),
 content jsonb not null check(jsonb_typeof(content)='object' and octet_length(content::text)<=5000000),
 published_at timestamptz not null default now(),
 published_by uuid references auth.users(id) on delete set null
);
alter table public.curriculum_releases enable row level security;
create policy read_published_curriculum on public.curriculum_releases for select to anon,authenticated using (true);
revoke all on public.curriculum_releases from anon,authenticated;
grant select(version,title,content,published_at) on public.curriculum_releases to anon,authenticated;
create table public.curriculum_draft (
 id integer primary key default 1 check(id=1),
 base_version integer not null references public.curriculum_releases(version),
 revision integer not null default 1 check(revision>0),
 title text not null,
 content jsonb not null check(jsonb_typeof(content)='object' and octet_length(content::text)<=5000000),
 updated_at timestamptz not null default now(),
 updated_by uuid references auth.users(id) on delete set null
);
alter table public.curriculum_draft enable row level security;
create policy editor_reads_draft on public.curriculum_draft for select to authenticated using ((select public.is_curriculum_editor()));
revoke all on public.curriculum_draft from anon,authenticated;
grant select on public.curriculum_draft to authenticated;
create function public.validate_curriculum(c jsonb, previous jsonb default null) returns void language plpgsql set search_path='' as $$
declare l jsonb; s jsonb; old jsonb; n jsonb;
begin
 if not extensions.jsonb_matches_schema('{"type":"object","properties":{"schemaVersion":{"const":1},"chapters":{"type":"array","items":{"type":"object","properties":{"id":{"type":"integer","minimum":1,"maximum":30},"title":{"type":"string","minLength":1,"maxLength":20000},"subtitle":{"type":"string","minLength":1,"maxLength":20000},"region":{"type":"string","minLength":1,"maxLength":20000}},"required":["id","title","subtitle","region"],"additionalProperties":false},"minItems":1,"maxItems":30},"lessons":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"chapter":{"type":"integer","minimum":1,"maximum":1000000},"order":{"type":"integer","minimum":1,"maximum":1000000},"title":{"type":"string","minLength":1,"maxLength":20000},"category":{"enum":["Technika","Rytm","Teoria","Słuch","Repertuar","Improwizacja"]},"theory":{"type":"string","minLength":1,"maxLength":20000},"steps":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"example":{"type":"string","minLength":1,"maxLength":20000},"criteria":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"mistake":{"type":"string","minLength":1,"maxLength":20000},"source":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"prerequisites":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":0,"maxItems":5000,"uniqueItems":true},"optional":{"type":"boolean"},"challenge":{"type":"boolean"},"minutes":{"type":"integer","minimum":1,"maximum":180},"sessions":{"type":"array","items":{"type":"integer","minimum":1,"maximum":1000000},"minItems":2,"maxItems":2},"branch":{"type":"string","minLength":1,"maxLength":20000},"songChoices":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":1,"maxItems":10,"uniqueItems":true}},"required":["id","chapter","order","title","category","theory","steps","example","criteria","mistake","source","prerequisites","optional","challenge","minutes"],"additionalProperties":false},"minItems":1,"maxItems":5000},"songs":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"title":{"type":"string","minLength":1,"maxLength":20000},"artist":{"type":"string","minLength":1,"maxLength":20000},"kind":{"enum":["Piosenka","Riff","Aranżacja"]},"chapter":{"type":"integer","minimum":1,"maximum":1000000},"version":{"type":"string","minLength":1,"maxLength":20000},"requirements":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":0,"maxItems":5000,"uniqueItems":true},"example":{"type":"string","maxLength":20000},"url":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000},"lesson":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"teacher":{"type":"string","minLength":1,"maxLength":20000},"language":{"type":"string","minLength":1,"maxLength":20000},"practice":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"criteria":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"nylon":{"type":"string","minLength":1,"maxLength":20000},"sessions":{"type":"array","items":{"type":"integer","minimum":1,"maximum":1000000},"minItems":2,"maxItems":2},"checkpoint":{"type":"integer","minimum":1,"maximum":1000000},"extraUrl":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000}},"required":["id","title","artist","kind","chapter","version","requirements","example"],"additionalProperties":false},"minItems":0,"maxItems":5000},"sources":{"type":"object","minProperties":1,"maxProperties":5000,"propertyNames":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"additionalProperties":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":20000},"url":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000},"language":{"type":"string","minLength":1,"maxLength":20000},"access":{"type":"string","minLength":1,"maxLength":20000}},"required":["title","url","language","access"],"additionalProperties":false}}},"required":["schemaVersion","chapters","lessons","songs","sources"],"additionalProperties":false}'::json,c) then raise exception 'Program nie spełnia schematu treści.'; end if;
 if exists(select 1 from jsonb_array_elements(c->'lessons') x group by x->>'id' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(c->'songs') x group by x->>'id' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(c->'chapters') x group by x->>'id' having count(*)>1) then raise exception 'Powtórzone identyfikatory.'; end if;
 if exists(select 1 from jsonb_array_elements(c->'chapters') with ordinality x(ch,idx) where (ch->>'id')::int<>idx) then raise exception 'Nieprawidłowa kolejność rozdziałów.'; end if;
 for l in select value from jsonb_array_elements(c->'lessons') loop
  if not exists(select 1 from jsonb_array_elements(c->'chapters') ch where ch->'id'=l->'chapter') or not(c->'sources' ? (l->>'source')) or exists(select 1 from jsonb_array_elements_text(l->'prerequisites') p where not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->>'id'=p)) then raise exception 'Nieistniejące wymaganie, rozdział lub źródło: %',l->>'id'; end if;
  if l ? 'sessions' and (l->'sessions'->>0)::int>(l->'sessions'->>1)::int then raise exception 'Odwrócony zakres sesji.'; end if;
  if l ? 'songChoices' then
   if not(l->>'challenge')::boolean then raise exception 'Wybór utworu musi być wyzwaniem.'; end if;
   for s in select value from jsonb_array_elements(l->'songChoices') loop
    select value into n from jsonb_array_elements(c->'songs') x where x->'id'=s;
    if n is null or not(n ? 'url') or not(n ? 'practice') or not(n ? 'criteria') or n->'checkpoint' is distinct from l->'chapter' then raise exception 'Niekompletny utwór sceny.'; end if;
   end loop;
  end if;
 end loop;
 for s in select value from jsonb_array_elements(c->'songs') loop
  if not exists(select 1 from jsonb_array_elements(c->'chapters') ch where ch->'id'=s->'chapter')
  or exists(select 1 from jsonb_array_elements_text(s->'requirements') p where not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->>'id'=p))
  or (s ? 'lesson' and not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->'id'=s->'lesson'))
  or (s ? 'checkpoint' and not exists(select 1 from jsonb_array_elements(c->'chapters') x where x->'id'=s->'checkpoint')) then raise exception 'Nieistniejące wymagania utworu.'; end if;
  if s ? 'sessions' and (s->'sessions'->>0)::int>(s->'sessions'->>1)::int then raise exception 'Odwrócony zakres sesji utworu.'; end if;
 end loop;
 if exists(with recursive edges as (select x->>'id' id,p dep from jsonb_array_elements(c->'lessons') x cross join lateral jsonb_array_elements_text(x->'prerequisites') p), walk as (select id,dep,array[id] path,dep=id cycle from edges union all select w.id,e.dep,w.path||w.dep,e.dep=any(w.path||w.dep) from walk w join edges e on e.id=w.dep where not w.cycle) select 1 from walk where cycle) then raise exception 'Pętla wymagań w programie.'; end if;
 if exists(select 1 from jsonb_array_elements(c->'chapters') ch where not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->'chapter'=ch->'id' and x->>'optional'='false')) or exists(select 1 from jsonb_array_elements(c->'lessons') x where x->>'optional'='false' group by x->>'chapter',x->>'order' having count(*)>1) then raise exception 'Rozdział bez trasy lub powtórzona kolejność.'; end if;
 if previous is not null then
  for old in select value from jsonb_array_elements(previous->'lessons') loop
   select value into n from jsonb_array_elements(c->'lessons') x where x->'id'=old->'id';
   if n is null or n->'challenge'<>old->'challenge' or n->'optional'<>old->'optional' or n->'chapter'<>old->'chapter' then raise exception 'Zachowaj identyfikatory, rozdział, rodzaj i XP opublikowanych zadań.'; end if;
   if (old ? 'songChoices' and not(coalesce(n->'songChoices','[]'::jsonb) @> (old->'songChoices'))) or (not(old ? 'songChoices') and n ? 'songChoices') then raise exception 'Zachowaj historyczne wybory utworów.'; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(previous->'songs') old where not exists(select 1 from jsonb_array_elements(c->'songs') x where x->'id'=old->'id')) or exists(select 1 from jsonb_array_elements(previous->'chapters') old where not exists(select 1 from jsonb_array_elements(c->'chapters') x where x->'id'=old->'id')) then raise exception 'Nie można usunąć opublikowanych utworów lub rozdziałów.'; end if;
 end if;
end;
$$;
revoke all on function public.validate_curriculum(jsonb,jsonb) from public,anon,authenticated;
create function public.start_curriculum_draft() returns public.curriculum_draft language plpgsql security definer set search_path='' as $$
declare r public.curriculum_releases; d public.curriculum_draft;
begin
 if not public.is_curriculum_editor() then raise exception 'Brak uprawnień do edycji programu.' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(20261021,1);
 select * into d from public.curriculum_draft where id=1;
 if found then return d; end if;
 select * into strict r from public.curriculum_releases order by version desc limit 1;
 insert into public.curriculum_draft(id,base_version,title,content,updated_by) values(1,r.version,'Aktualizacja programu',r.content,auth.uid()) returning * into d;
 return d;
end;
$$;
create function public.save_curriculum_draft(expected_revision integer, next_title text, next_content jsonb) returns public.curriculum_draft language plpgsql security definer set search_path='' as $$
declare d public.curriculum_draft;
begin
 if not public.is_curriculum_editor() then raise exception 'Brak uprawnień do edycji programu.' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(20261021,1);
 if length(trim(next_title)) not between 1 and 200 then raise exception 'Podaj nazwę wersji (1–200 znaków).'; end if;
 update public.curriculum_draft set title=next_title,content=next_content,revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=1 and revision=expected_revision returning * into d;
 if not found then raise exception 'Wersja robocza zmieniła się w innej karcie. Pobierz ją ponownie; Twoje zmiany pozostają w formularzu.' using errcode='40001'; end if;
 return d;
end;
$$;
create function public.publish_curriculum_draft(expected_revision integer) returns integer language plpgsql security definer set search_path='' as $$
declare d public.curriculum_draft; r public.curriculum_releases; next_version integer;
begin
 if not public.is_curriculum_editor() then raise exception 'Brak uprawnień do publikacji programu.' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(20261021,1);
 select * into d from public.curriculum_draft where id=1 and revision=expected_revision for update;
 if not found then raise exception 'Wersja robocza zmieniła się. Pobierz ją ponownie przed publikacją.' using errcode='40001'; end if;
 select * into strict r from public.curriculum_releases order by version desc limit 1;
 if d.base_version<>r.version then raise exception 'Program ma już nowszą publikację. Pobierz aktualną wersję.' using errcode='40001'; end if;
 perform public.validate_curriculum(d.content,r.content);
 next_version:=r.version+1;
 insert into public.curriculum_releases(version,title,content,published_by) values(next_version,d.title,d.content,auth.uid());
 delete from public.curriculum_draft where id=1;
 return next_version;
end;
$$;
revoke all on function public.start_curriculum_draft(),public.save_curriculum_draft(integer,text,jsonb),public.publish_curriculum_draft(integer) from public,anon;
grant execute on function public.start_curriculum_draft(),public.save_curriculum_draft(integer,text,jsonb),public.publish_curriculum_draft(integer) to authenticated;
insert into public.curriculum_releases(version,title,content) values(2,'Gitara klasyczna · program rozszerzony','{"schemaVersion":1,"chapters":[{"id":1,"title":"Pierwsze dźwięki","subtitle":"Poznaj gitarę. Znajdź swój puls.","region":"PUNKT WYJŚCIA"},{"id":2,"title":"Pierwsze piosenki","subtitle":"Kilka akordów. Cały nowy świat.","region":"DOLINA AKORDÓW"},{"id":3,"title":"Rytm i melodie","subtitle":"Niech dźwięki zaczną opowiadać.","region":"SZLAK RYTMU"},{"id":4,"title":"Rozumiem gryf","subtitle":"Połącz dźwięki w jedną mapę.","region":"OBSERWATORIUM"},{"id":5,"title":"Pierwsza improwizacja","subtitle":"Zagraj coś, czego jeszcze nie było.","region":"POLANA POMYSŁÓW"},{"id":6,"title":"Fingerstyle","subtitle":"Melodia i bas w Twoich dłoniach.","region":"MOST STRUN"},{"id":7,"title":"Swobodne akordy","subtitle":"Te same harmonie, nowe miejsca.","region":"PRZEŁĘCZ HARMONII"},{"id":8,"title":"Improwizacja świadoma","subtitle":"Usłysz akord. Odpowiedz frazą.","region":"RZEKA MELODII"},{"id":9,"title":"Własne aranżacje","subtitle":"Nadaj piosence własne brzmienie.","region":"PRACOWNIA"},{"id":10,"title":"Samodzielny muzyk","subtitle":"Twój repertuar. Twój głos.","region":"OTWARTY HORYZONT"}],"lessons":[{"id":"ch-01-1","chapter":1,"order":1,"title":"Poznaj swoje sześć strun","category":"Technika","theory":"Struny numerujemy od najcieńszej: 1 to wysokie E, 6 to niskie E. Standardowy strój od najgrubszej to E–A–D–G–B–E. W międzynarodowych materiałach B oznacza polskie H, a B♭ — polskie B.","steps":["Połóż gitarę stabilnie i wskaż struny 1 i 6.","Zagraj każdą pustą strunę kciukiem od 6 do 1, wypowiadając nazwę.","Odwróć kolejność i powtórz bez patrzenia na opis."],"example":"6 → 1: E2 · A2 · D3 · G3 · B3 · E4","criteria":["Wskaż wszystkie sześć strun po numerze.","Nazwij struny w obu kierunkach bez podpowiedzi."],"mistake":"Nie myl numeru struny z wysokością dźwięku: pierwsza jest najcieńsza.","source":"classical","prerequisites":[],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-01-2","chapter":1,"order":2,"title":"Nastrój gitarę","category":"Słuch","theory":"Strojenie zaczyna się przed ćwiczeniem. Struna zbyt niska wymaga zwiększenia napięcia, zbyt wysoka — zmniejszenia. Korzystaj z osobnego tunera chromatycznego; aplikacja nie analizuje mikrofonu.","steps":["Otwórz tuner lub użyj stroika i wybierz strój EADGBE.","Szarp jedną strunę, sprawdź właściwy klucz i obracaj go małymi ruchami.","Nastrój sześć strun, potem sprawdź je ponownie."],"example":"Cele: E2 82,41 Hz · A2 110 · D3 146,83 · G3 196 · B3 246,94 · E4 329,63","criteria":["Tuner potwierdza właściwą nazwę i oktawę każdej struny.","Po ponownym sprawdzeniu wszystkie struny pozostają nastrojone."],"mistake":"Nie napinaj struny do przypadkowego E w wyższej oktawie. Najpierw sprawdź nazwę i oktawę.","source":"ch-01-2-source","prerequisites":["ch-01-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-01-3","chapter":1,"order":3,"title":"Wygodna pozycja","category":"Technika","theory":"Gitara ma być stabilna bez ściskania gryfu. Podparcie instrumentu pozwala dłoniom poruszać się swobodnie. Wybierz podnóżek lub podpórkę, jeśli pomaga utrzymać neutralną pozycję.","steps":["Usiądź na stabilnym krześle i ustaw gitarę tak, by gryf był lekko uniesiony.","Puść lewą dłoń: instrument powinien pozostać stabilny.","Zagraj puste struny, opuść barki i sprawdź, czy możesz spokojnie oddychać."],"example":"30 sekund gry → krótka pauza → sprawdzenie barków i nadgarstków","criteria":["Utrzymaj stabilny instrument bez zaciskania lewej dłoni.","Zagraj minutę swobodnie; przy bólu przerwij i popraw pozycję."],"mistake":"Nie unoś barku, żeby dosięgnąć strun; dopasuj pozycję instrumentu.","source":"ch-01-3-source","prerequisites":["ch-01-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-01-4","chapter":1,"order":4,"title":"Twoja prawa dłoń: p–i–m–a","category":"Technika","theory":"p to kciuk, i wskazujący, m środkowy, a serdeczny. Przy swobodnym szarpnięciu (tirando) palec nie opiera się na sąsiedniej strunie. Ruch jest mały, a dźwięk równy.","steps":["Oprzyj kciuk przy strunie 5, a i–m–a przygotuj nad 3–2–1.","Zagraj po kolei p–i–m–a, pozwalając dźwiękom wybrzmieć.","Powtórz osiem razy powoli, zachowując rozluźnienie."],"example":"p(5) – i(3) – m(2) – a(1)","criteria":["Wykonaj osiem cykli bez zaczepiania sąsiednich strun.","Dźwięki mają zbliżoną głośność."],"mistake":"Nie odciągaj palców daleko od strun po każdym dźwięku.","source":"ch-01-4-source","prerequisites":["ch-01-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-01-5","chapter":1,"order":5,"title":"Pierwszy próg, czysty dźwięk","category":"Technika","theory":"Próg skraca drgającą część struny. Palec stawiamy tuż przed metalowym progiem, od strony główki, używając tylko potrzebnego nacisku.","steps":["Na pierwszej strunie zagraj pustą E, potem próg 1 palcem wskazującym.","Przesuń palec bliżej progu, jeśli dźwięk brzęczy.","Zagraj progi 1–2–3 palcami 1–2–3 i wróć do pustej struny."],"example":"Struna 1: 0 – 1 – 2 – 3 – 2 – 1 – 0","criteria":["Zagraj sekwencję trzy razy z czystymi dźwiękami.","Zwolnij nacisk po ćwiczeniu i sprawdź rozluźnienie dłoni."],"mistake":"Nie dociskaj na samym metalowym progu ani nie ściskaj gryfu na zapas.","source":"classical","prerequisites":["ch-01-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-01-6","chapter":1,"order":6,"title":"Złap puls","category":"Rytm","theory":"Puls to regularne uderzenia, do których odnosimy rytm. Najpierw wyczuj go ruchem i głosem, potem dodaj instrument.","steps":["Ustaw metronom na 60 BPM i licz 1–2–3–4.","Klaszcz na każde kliknięcie przez cztery takty.","Zagraj pustą strunę 1 na każdy puls przez osiem taktów."],"example":"| 1 2 3 4 | 1 2 3 4 | — jeden dźwięk na klik","criteria":["Utrzymaj osiem taktów bez zatrzymania.","Potrafisz wrócić do pulsu po pojedynczej pomyłce."],"mistake":"Nie przyspieszaj między kliknięciami; najpierw posłuchaj dwóch taktów.","source":"beginner","prerequisites":["ch-01-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-01-7","chapter":1,"order":7,"title":"Czytaj tabulaturę i diagram","category":"Teoria","theory":"W tabulaturze górna linia to cienka struna 1. Cyfra oznacza próg, 0 pustą strunę. Na diagramie akordu X oznacza strunę pomijaną, a O pustą. Sama tabulatura bez wartości rytmicznych nie określa czasu.","steps":["Przeczytaj poniższy przykład od lewej do prawej.","Zagraj na pierwszej strunie jeden dźwięk na klik przy 60 BPM.","W warsztacie otwórz Em i wskaż dwie dociskane struny."],"example":"e|–0–1–3–1–0–|  B|———————————|  cyfry: numery progów","criteria":["Zagraj przykład bez mylenia struny i progu.","Wyjaśnij znaczenie 0 oraz X na diagramie."],"mistake":"Nie czytaj górnej linii jako najgrubszej struny.","source":"theory","prerequisites":["ch-01-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-01-1","chapter":1,"order":8,"title":"Minimalny nacisk, czysty dźwięk","category":"Technika","theory":"Czysty dźwięk wymaga kontaktu struny z progiem, nie ściskania całego gryfu. Szukanie minimalnego nacisku ułatwi później akordy.","steps":["Zagraj F na 1/1, kładąc palec tuż za progiem.","Stopniowo zmniejszaj nacisk do brzęczenia, potem dodaj tylko tyle, by dźwięk był czysty.","Powtórz na 2/1 i 3/2; po każdej próbie całkowicie rozluźnij dłoń."],"example":"1/1 oznacza: struna 1, próg 1. Docisk → odpuszczenie → czysty dźwięk.","criteria":["Wydobądź po pięć czystych dźwięków w trzech miejscach.","Po każdej serii potrafisz od razu rozluźnić kciuk."],"mistake":"Ból jest sygnałem do przerwy, nie kryterium skutecznego treningu.","source":"technique","prerequisites":["ch-01-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-01-2","chapter":1,"order":9,"title":"Tirando i apoyando","category":"Technika","theory":"Tirando kończy ruch palca poza sąsiednią struną; w apoyando palec opiera się na sąsiedniej, grubszej strunie. Oba sposoby służą kontroli brzmienia.","steps":["Zagraj osiem dźwięków E na strunie 1 tirando.","Powtórz apoyando, opierając palec na strunie 2 bez uderzania w nią.","Zagraj E–F–G–F, porównując oba sposoby przy 50 BPM."],"example":"i–m tirando → i–m apoyando; kciuk pozostaje swobodny.","criteria":["Zagraj motyw dwoma sposobami i nazwij różnicę.","Sąsiednia struna nie wydaje przypadkowego dźwięku."],"mistake":"Nie wpychaj całej dłoni w struny. Zmienia się tor ruchu palca.","source":"technique","prerequisites":["deep-01-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-01-3","chapter":1,"order":10,"title":"Puls wewnętrzny: klik i cisza","category":"Rytm","theory":"Metronom sprawdza puls, ale nie powinien być jedynym powodem, dla którego wiesz, kiedy zagrać. Liczenie trwa także w ciszy.","steps":["Ustaw 60 BPM i licz cztery takty na głos.","W następnym takcie graj tylko na 1 i 3, licząc pozostałe pulsy.","Zatrzymaj metronom na cztery liczone pulsy i uruchom ponownie; porównaj własne tempo."],"example":"1 graj · 2 licz · 3 graj · 4 licz.","criteria":["Zagraj osiem taktów bez przyspieszania pauz.","Po ciszy wracasz na właściwy numer pulsu."],"mistake":"Nie traktuj przypadkowego momentu uruchomienia metronomu jako testu idealnej synchronizacji. Oceniaj tempo.","source":"meter","prerequisites":["deep-01-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-01-4","chapter":1,"order":11,"title":"Przejście przez trzy struny","category":"Technika","theory":"Zmiana struny jest osobną umiejętnością. Oko patrzy na cel, a dłoń wykonuje mały ruch, bez odrywania ramienia.","steps":["Na pustych strunach 1, 2 i 3 zagraj po dwa dźwięki i–m.","Wróć 3–2–1 przy 50 BPM.","Zmień wzór na po trzy dźwięki na strunę; zachowaj naprzemienność także na granicy."],"example":"1: i m i · 2: m i m · 3: i m i.","criteria":["Wykonaj cztery obiegi obu wzorów.","Nie powtarzasz palca przy każdej zmianie struny."],"mistake":"Nie przyspieszaj przejścia, aby ukryć brak kontroli.","source":"technique","prerequisites":["deep-01-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-01-5","chapter":1,"order":12,"title":"Dźwięk, pauza i wyciszenie","category":"Rytm","theory":"Pauza oznacza zaplanowaną ciszę. Na gitarze często trzeba ją wykonać ruchem tłumiącym, bo struna sama nadal brzmi.","steps":["Zagraj pustą strunę 1 na 1 i dotknij jej delikatnie na 2.","Zagraj na 3 i wycisz na 4; powtarzaj przy 60 BPM.","Zagraj dźwięk trwający dwa pulsy, potem dwa pulsy ciszy."],"example":"| E cisza E cisza | E — cisza cisza |","criteria":["Zagraj osiem taktów z równymi pauzami.","Wyciszenie nie produkuje dodatkowego szarpnięcia."],"mistake":"Nie zaciskaj lewej ręki, gdy możesz wyciszyć strunę prawą.","source":"meter","prerequisites":["deep-01-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-01-6","chapter":1,"order":13,"title":"Ucz się frazy, nie szeregu progów","category":"Słuch","theory":"Rozpoznawalna melodia ma kierunek i zakończenie. Głos pomaga zapamiętać ją jako całość, nawet zanim poznasz nazwy wszystkich nut.","steps":["Zagraj na strunie 1 progi 0–1–3–1, po jednej ćwierćnucie.","Zaśpiewaj ten sam kierunek bez gitary.","Zagraj z pamięci, następnie zmień ostatni dźwięk na 0 i porównaj zakończenia."],"example":"E F G F → E F G E; cztery pulsy na frazę.","criteria":["Odtwórz oba warianty po krótkiej przerwie.","Potrafisz zanucić kierunek przed zagraniem."],"mistake":"Nie oceniaj swojego głosu jak występu. To sposób sprawdzenia pamięci muzycznej.","source":"ear","prerequisites":["deep-01-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-01-8","chapter":1,"order":14,"title":"Wyzwanie: Twoja pierwsza melodia","category":"Repertuar","theory":"Krótki motyw to już muzyka, gdy ma puls i wyraźne zakończenie. To autorskie ćwiczenie na jednej strunie, po jednym dźwięku na ćwierćnutę.","steps":["Nastrój gitarę i przećwicz osobno oba takty.","Zagraj przykład przy 60 BPM, licząc do czterech.","Powtórz trzy razy, kończąc ostatnie E spokojnym wybrzmieniem."],"example":"Struna 1: | 0 1 3 1 | 0 3 1 0 |","criteria":["Zagraj trzy pełne powtórzenia bez zatrzymywania pulsu.","Usłysz czysto wszystkie dźwięki i rozluźnij ręce na końcu."],"mistake":"Nie zaczynaj od maksymalnego tempa; stabilne 60 BPM wystarczy.","source":"classical","prerequisites":["deep-01-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-01","chapter":1,"order":15,"title":"Scena 1: Pierwsza znana melodia","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-01-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[5,12],"songChoices":["rep-ode-melody","rep-twinkle","rep-seven"]},{"id":"side-01-1","chapter":1,"order":1,"title":"Odpoczynek też jest ćwiczeniem","category":"Technika","theory":"Krótka pauza pozwala sprawdzić napięcie. Świadoma obserwacja jakości ruchu jest częścią nauki.","steps":["Zagraj puste struny przez 30 sekund.","Odłóż ręce i sprawdź barki, oddech oraz nacisk.","Powtórz trzy cykle, kończąc zanim pojawi się zmęczenie."],"example":"30 s gry / 20 s odpoczynku × 3","criteria":["Rozpoznaj i zmniejsz jedno zbędne napięcie."],"mistake":"Nie graj przez ból.","source":"ch-01-3-source","prerequisites":["ch-01-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-01-2","chapter":1,"order":2,"title":"Echo na pustych strunach","category":"Słuch","theory":"Krótki rytm można powtórzyć bez znajomości akordów.","steps":["Wyklaszcz cztery pulsy z jedną pauzą.","Powtórz rytm na pustej E.","Zmień miejsce pauzy i powtórz."],"example":"| E – E E | → | E E – E |","criteria":["Odtwórz trzy rytmy z zachowaniem ciszy."],"mistake":"Nie skracaj taktu przy pauzie.","source":"ear","prerequisites":["ch-01-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Słuch i czytanie"},{"id":"branch-01-1","chapter":1,"order":3,"title":"Barwa przy mostku i otworze","category":"Technika","theory":"Miejsce szarpnięcia zmienia barwę bez zmiany wysokości. Ucho prowadzi dłoń do wybranego koloru.","steps":["Zagraj E nad otworem rezonansowym.","Przesuń prawą dłoń bliżej mostka i porównaj.","Wykonaj cztery krótkie frazy, zmieniając miejsce dopiero między nimi."],"example":"Ta sama nuta, dwa kolory: miękki i jasny.","criteria":["Odtwórz oba kolory bez zmiany tempa."],"mistake":"Nie zwiększaj siły, próbując uzyskać jaśniejszą barwę.","source":"technique","prerequisites":["ch-01-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Klasyka"},{"id":"branch-01-2","chapter":1,"order":4,"title":"Echo dwóch dźwięków","category":"Słuch","theory":"Pamięć wysokości trenuje się w małych porcjach. Wystarczy krótka przerwa między wzorem a odpowiedzią.","steps":["Zagraj E–G na pierwszej strunie.","Odczekaj cztery pulsy i zanuć parę.","Odtwórz ją, potem sprawdź E–F oraz G–E."],"example":"Wzór → 4 pulsy ciszy → głos → gitara.","criteria":["Powtórz poprawnie cztery z pięciu par."],"mistake":"Nie zamieniaj tego ćwiczenia w bezmyślne powtarzanie ruchu bez słuchania.","source":"ear","prerequisites":["ch-01-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Słuch i czytanie"},{"id":"branch-01-3","chapter":1,"order":5,"title":"Palcowanie zapisane na przyszłość","category":"Technika","theory":"Cyfry 1–4 opisują palce lewej dłoni, a p–i–m–a prawej. Stałe palcowanie ułatwia pamięć.","steps":["Zapisz progi 0–1–3–1 dla pierwszej struny.","Dopisz palce lewej ręki: 0–1–3–1 i prawej i–m–i–m.","Zagraj pięć razy identycznie, a jutro sprawdź odczyt."],"example":"Lewa 1 = wskazujący, 4 = mały; prawa a = serdeczny.","criteria":["Odczytaj swój zapis po przerwie i wykonaj go bez zmiany palców."],"mistake":"Numer struny, progu i palca to trzy różne informacje.","source":"classical","prerequisites":["ch-01-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Klasyka"},{"id":"ch-02-1","chapter":2,"order":1,"title":"Pierwszy akord: Em","category":"Technika","theory":"Akord to kilka dźwięków brzmiących razem. Em zawiera E, G i B. Kształt 022000 czytamy od szóstej struny do pierwszej.","steps":["Dociśnij struny 5 i 4 na drugim progu palcami 2 i 3.","Zagraj osobno wszystkie struny i popraw te, które nie brzmią.","Przeciągnij kciukiem po sześciu strunach, potem puść chwyt."],"example":"Em: 0–2–2–0–0–0","criteria":["Pięć razy ułóż chwyt z czystymi sześcioma strunami.","Potrafisz nazwać podstawowy dźwięk akordu: E."],"mistake":"Nie dotykaj przypadkiem pustej struny G bokiem palca.","source":"beginner","prerequisites":["rep-01"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-02-2","chapter":2,"order":2,"title":"Akordy Am i E","category":"Technika","theory":"Przesunięcie podobnego układu palców o strunę pozwala poznać dwa różne akordy. Am gramy od struny 5, E od struny 6.","steps":["Ułóż Am: x02210 i sprawdź każdą strunę.","Ułóż E: 022100, zachowując zaokrąglone palce.","Zagraj cztery wolne uderzenia Am i cztery E."],"example":"Am: x–0–2–2–1–0   E: 0–2–2–1–0–0","criteria":["Oba chwyty brzmią czysto w trzech kolejnych próbach.","W Am pomijasz najgrubszą strunę."],"mistake":"Nie traktuj X jak pustej struny: jej nie gramy.","source":"beginner","prerequisites":["ch-02-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-02-3","chapter":2,"order":3,"title":"Zmiany bez zatrzymania","category":"Rytm","theory":"Zmiana akordu jest częścią rytmu. W wolnym tempie przygotuj następny chwyt przed pierwszym uderzeniem kolejnego taktu.","steps":["Ustaw 50 BPM i graj Em tylko na pierwsze uderzenie taktu.","W kolejnym takcie zagraj Am; pozostałe pulsy wykorzystaj na zmianę.","Po ośmiu taktach spróbuj dwóch uderzeń na takt."],"example":"| Em – – – | Am – – – |","criteria":["Wykonaj osiem taktów zmian w równym pulsie.","Policz poprawne zmiany i zapisz wynik w notatce."],"mistake":"Nie przyspieszaj łatwego akordu i nie zwalniaj trudnego.","source":"beginner","prerequisites":["ch-02-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-02-4","chapter":2,"order":4,"title":"Dodaj C, G i D","category":"Technika","theory":"Akordy C, G i D otwierają wiele progresji. Ucz się pojedynczego chwytu w jednej sesji; cały zestaw może wymagać kilku dni.","steps":["Sprawdź kolejno C x32010, G 320003 i D xx0232.","Zagraj każdą strunę osobno, pomijając X.","Ćwicz C–G, a w następnej sesji G–D, po cztery pulsy na akord."],"example":"C x32010 · G 320003 · D xx0232","criteria":["Każdy chwyt brzmi czysto trzy razy.","Wykonaj cztery spokojne zmiany każdej pary."],"mistake":"W D zacznij od czwartej struny; nie uderzaj wszystkich sześciu.","source":"beginner","prerequisites":["ch-02-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-02-5","chapter":2,"order":5,"title":"Ćwierćnuty, ósemki i cisza","category":"Rytm","theory":"Dwie ósemki mieszczą się w jednej ćwierćnucie. Liczenie „1 i 2 i” pomaga rozdzielić puls od podziału. Pauza zajmuje czas tak samo jak dźwięk.","steps":["Na tłumionych strunach zagraj ćwierćnuty przy 60 BPM.","Dodaj ósemki, licząc 1-i-2-i-3-i-4-i.","Zagraj wzór z pauzą na drugim pulsie; dłoń nadal utrzymuje ruch."],"example":"| dźwięk, pauza, dwa krótkie, dźwięk |","criteria":["Wykonaj osiem taktów bez skracania pauzy.","Rozróżnij osiem ósemek i cztery ćwierćnuty w takcie 4/4."],"mistake":"Nie zatrzymuj wewnętrznego liczenia podczas ciszy.","source":"theory","prerequisites":["ch-02-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-02-6","chapter":2,"order":6,"title":"Pierwsze bicie palcami","category":"Rytm","theory":"Do akompaniamentu na nylonowych strunach wystarczy lekki ruch palca wskazującego lub kciuka. Głośność nie wymaga sztywnego nadgarstka.","steps":["Przećwicz ruch w dół na tłumionych strunach.","Na Em zagraj cztery ćwierćnuty, akcentując lekko 1.","Połącz Em i Am po jednym takcie przez minutę przy 60 BPM."],"example":"↓ ↓ ↓ ↓   | Em | Am |","criteria":["Utrzymaj minutę bicia z równym pulsem.","Nie zagłuszaj rytmu przypadkowymi mocnymi uderzeniami."],"mistake":"Ruch ma być niewielki; nie szarp strun całym ramieniem.","source":"beginner","prerequisites":["ch-02-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-02-7","chapter":2,"order":7,"title":"Usłysz dur i moll","category":"Słuch","theory":"Akordy durowy i molowy różnią się tercją. E ma G♯, Em ma G. Kojarzenie brzmienia z emocją bywa pomocne, ale najważniejsze jest usłyszenie różnicy.","steps":["Zagraj E, następnie Em, zmieniając tylko pierwszy próg struny 3.","Zaśpiewaj zmieniający się dźwięk G♯–G.","W warsztacie wykonaj quiz dur/moll z różnymi dźwiękami podstawowymi."],"example":"E = E G♯ B   Em = E G B","criteria":["Uzyskaj co najmniej 8 poprawnych odpowiedzi na 10 w quizie.","Pokaż na gitarze dźwięk różniący E od Em."],"mistake":"Nie zgaduj wyłącznie po głośności; słuchaj tercji.","source":"ear","prerequisites":["ch-02-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-02-1","chapter":2,"order":8,"title":"Osiem akordów otwartych","category":"Technika","theory":"E, Em, A, Am, D, Dm, C i G tworzą bazę wielu akompaniamentów. Nie muszą być opanowane w jeden dzień.","steps":["Porównaj E 022100 z Em 022000 oraz A x02220 z Am x02210.","Dodaj D xx0232 i Dm xx0231; sprawdź osobno każdą strunę.","Przez kolejne sesje losuj po cztery z ośmiu chwytów i wracaj do C oraz G."],"example":"Od struny 6 do 1: x = nie graj, 0 = pusta struna.","criteria":["Ustaw wszystkie osiem akordów z pamięci, bez wymogu szybkości.","W każdym chwycie słychać wszystkie zamierzone struny."],"mistake":"W D i Dm nie uderzaj wszystkich sześciu strun.","source":"chordmap","prerequisites":["ch-02-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-02-2","chapter":2,"order":9,"title":"Palec prowadzący i wspólne dźwięki","category":"Technika","theory":"Wspólny palec może skrócić zmianę, ale tylko jeśli pasuje do obu chwytów. Inne palce poruszają się jednocześnie.","steps":["Zmieniaj Am x02210 na C x32010, pozostawiając palec na 2/1.","Sprawdź wolno, które pozostałe palce muszą zmienić miejsce.","Zagraj po dwa pulsy Am i C przez osiem taktów przy 50 BPM."],"example":"Am → C: wspólne 2/1 i 4/2, zmienia się bas.","criteria":["Zagraj osiem taktów bez dodatkowego pulsu na zmianę.","Potrafisz wyjaśnić, który palec pozostaje na miejscu."],"mistake":"Nie utrzymuj na siłę palca, jeśli blokuje wygodną pozycję dłoni.","source":"technique","prerequisites":["deep-02-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-02-3","chapter":2,"order":10,"title":"Zmiany akordów pod zegarem","category":"Technika","theory":"Licznik zmian jest narzędziem obserwacji, nie wyścigiem. Licz tylko chwyt, który rzeczywiście zabrzmiał czysto.","steps":["Wybierz trudną parę, np. C–G. Przez minutę zmieniaj i delikatnie uderzaj każdy chwyt.","Zapisz liczbę czystych zmian oraz błąd, który pojawia się najczęściej.","Ćwicz sam ruch przez dwie minuty, następnie sprawdź ponownie przy równym pulsie."],"example":"Sesja 1: liczba czystych zmian; sesja 2: porównanie przy tym samym tempie.","criteria":["Zagraj tę parę w ośmiu taktach przy 50 BPM, zmiana co dwa pulsy.","W dwóch sesjach utrzymujesz czystość, nie tylko większą liczbę."],"mistake":"Nie zaliczaj bezgłośnego ułożenia palców jako czystej zmiany.","source":"practice","prerequisites":["deep-02-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-02-4","chapter":2,"order":11,"title":"Ręka rytmiczna nie zatrzymuje się","category":"Rytm","theory":"Ruch dłoni wyznacza podział czasu także wtedy, gdy nie dotyka strun. To przygotowanie do rytmów z opuszczonym uderzeniem.","steps":["Na Em poruszaj dłonią dół–góra w równych ósemkach przy 50 BPM.","Dotykaj strun tylko w dół, ruch w górę wykonuj w powietrzu.","Dodaj uderzenie w górę po 2 i 4; policz na głos każdy podział."],"example":"1 i 2 i 3 i 4 i: dół – dół góra dół – dół góra.","criteria":["Utrzymaj wzór przez osiem taktów.","Zmiana na Am nie zatrzymuje ruchu dłoni."],"mistake":"Nie usztywniaj nadgarstka i nie uderzaj paznokciem z dużą siłą.","source":"beginner","prerequisites":["deep-02-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-02-5","chapter":2,"order":12,"title":"Mapa piosenki: zwrotka i refren","category":"Repertuar","theory":"Znajomość czterech chwytów nie wystarcza, jeśli gubisz ich kolejność. Prosta mapa sekcji zmniejsza obciążenie pamięci.","steps":["Wybierz jedną z piosenek rozdziału i obejrzyj demonstrację nauczyciela.","Zapisz symbole sekcji A i B oraz liczbę obiegów akordów w każdej.","Zagraj akompaniament, śledząc mapę; zaznacz miejsce, w którym zwykle się mylisz."],"example":"A × 2 → B × 2 → A → B; to przykład formy, nie zapis konkretnej piosenki.","criteria":["Zagraj wybraną sekwencję sekcji od początku do końca.","Wiesz, który akord rozpoczyna każdą sekcję."],"mistake":"Nie przenoś przykładowej formy na utwór bez sprawdzenia jego lekcji.","source":"marty","prerequisites":["deep-02-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-02-6","chapter":2,"order":13,"title":"Próba ciągła po pomyłce","category":"Repertuar","theory":"Na próbie fragmentu poprawiasz błędy. W próbie ciągłej ćwiczysz utrzymanie czasu i powrót w następnym takcie. To dwa różne zadania.","steps":["Zagraj osiem taktów Em–Am–C–G po dwa takty na akord.","Jeśli pomylisz chwyt, pomiń uderzenie i wróć na początek następnego taktu.","Po zakończeniu wybierz jedną trudną zmianę, popraw ją osobno i wykonaj drugi przebieg."],"example":"Ćwiczenie szczegółu → próba całości → jedna poprawka → całość.","criteria":["Wykonaj dwa przebiegi bez restartowania od początku.","Potrafisz wskazać jeden poprawiony problem."],"mistake":"Kontynuowanie nie znaczy ignorowania błędów w każdej sesji.","source":"practice","prerequisites":["deep-02-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-02-8","chapter":2,"order":14,"title":"Wyzwanie: pierwsza cała piosenka","category":"Repertuar","theory":"Pełne wykonanie wymaga pamiętania formy. Wybierz prostą aranżację piosenki z repertuaru albo autorski ośmiotaktowy akompaniament poniżej.","steps":["Przećwicz trudną zmianę osobno.","Zagraj osiem taktów przykładu, po cztery ćwierćnuty na takt przy 60 BPM.","Powtórz całość dwa razy bez przerwy i zakończ na Em."],"example":"| Em | Am | Em | Am | C | G | Am | Em |","criteria":["Zagraj pełną formę dwukrotnie w równym tempie.","Wykorzystaj przynajmniej trzy poznane akordy."],"mistake":"Nie wracaj do początku po każdej pomyłce; ćwicz także kontynuowanie.","source":"beginner","prerequisites":["deep-02-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-02","chapter":2,"order":15,"title":"Scena 2: Piosenka przy ognisku","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-02-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[5,12],"songChoices":["song-04","rep-horse","song-09"]},{"id":"side-02-1","chapter":2,"order":1,"title":"Piosenka na dwóch akordach","category":"Repertuar","theory":"Ograniczony zestaw chwytów pozwala skupić się na ciągłości akompaniamentu.","steps":["Wybierz Em i Am.","Zagraj po dwa takty każdego akordu.","Powtórz cztery razy z prostą nuconą melodią."],"example":"| Em | Em | Am | Am | × 4","criteria":["Zagraj pełną formę bez zatrzymania."],"mistake":"Nie zmieniaj rytmu przypadkowo przy zmianie chwytu.","source":"beginner","prerequisites":["ch-02-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-02-2","chapter":2,"order":2,"title":"Arpeggio zamiast bicia","category":"Technika","theory":"Ten sam akord może zabrzmieć zupełnie inaczej, gdy rozdzielisz struny.","steps":["Ułóż Am.","Zagraj p5–i3–m2–i3 jako ćwierćnuty.","Powtórz na C przez osiem taktów."],"example":"p i m i · p i m i","criteria":["Zachowaj równe odstępy przez osiem taktów."],"mistake":"Nie urywaj poprzedniego dźwięku niepotrzebnym dotknięciem.","source":"technique","prerequisites":["ch-02-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"branch-02-1","chapter":2,"order":3,"title":"Dominanty otwarte E7, A7 i B7","category":"Technika","theory":"Trzy otwarte akordy septymowe pozwolą później zagrać bluesa. Na razie celem jest ich czyste brzmienie.","steps":["Sprawdź E7 020100 i A7 x02020 pojedynczymi strunami.","Dodaj B7 x21202 bez struny 6.","Zagraj E7–A7–B7–E7 po jednym takcie przy 45 BPM."],"example":"E7 → A7 → B7 → E7, po cztery spokojne uderzenia.","criteria":["Zagraj cztery obiegi z czystymi chwytami."],"mistake":"B7 wymaga przygotowania kilku palców; nie ucz się go w pośpiechu.","source":"sevenths","prerequisites":["ch-02-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Blues"},{"id":"branch-02-2","chapter":2,"order":4,"title":"Kciuk zamiast bicia","category":"Technika","theory":"Akompaniament może zaczynać się od samego basu. Pryma akordu pomaga usłyszeć harmonię nawet bez pełnego chwytu.","steps":["Na Em graj pustą 6, na Am pustą 5.","Dodaj C na 5/3 oraz G na 6/3.","Zagraj po cztery równe basy każdego akordu."],"example":"Em: E · Am: A · C: C · G: G.","criteria":["Zagraj 16 taktów z równą głośnością basów."],"mistake":"Nie szarp kciukiem tak mocno, by struna uderzała o progi.","source":"technique","prerequisites":["ch-02-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Fingerstyle"},{"id":"branch-02-3","chapter":2,"order":5,"title":"Dur i moll w porównaniu","category":"Słuch","theory":"Porównanie akordów od tej samej podstawy izoluje zmianę tercji. Em i E różnią się jednym dźwiękiem w chwycie.","steps":["Zagraj Em, potem E, słuchając struny 3.","Zaśpiewaj G oraz G♯ osobno.","Powtórz z Am i A, po czym opisz różnicę własnymi słowami."],"example":"Em → E: G → G♯; Am → A: C → C♯.","criteria":["Wskaż zmieniony dźwięk w obu parach."],"mistake":"Dur nie musi oznaczać wesołej muzyki, a moll smutnej.","source":"triads","prerequisites":["ch-02-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Słuch i czytanie"},{"id":"ch-03-1","chapter":3,"order":1,"title":"Walc i cztery czwarte","category":"Rytm","theory":"Metrum grupuje pulsy. W 3/4 liczysz trzy ćwierćnuty w takcie, w 4/4 cztery. Pierwszy puls pomaga słyszeć początek grupy.","steps":["Ustaw metronom 60 BPM i akcent co trzy uderzenia.","Na Am graj bas kciukiem na 1 i dwie lekkie odpowiedzi na 2–3.","Przełącz na cztery i dodaj trzecią odpowiedź."],"example":"3/4: BAS–akord–akord   4/4: BAS–akord–akord–akord","criteria":["Zagraj osiem taktów w każdym metrum.","Umiesz policzyć na głos grupy bez zgubienia pierwszego pulsu."],"mistake":"Nie myl 3/4 z trzema równymi dźwiękami w jednym pulsie.","source":"theory","prerequisites":["rep-02"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-03-2","chapter":3,"order":2,"title":"Graj ciszej, graj wyraźniej","category":"Technika","theory":"Dynamika to kontrola głośności. Crescendo oznacza stopniowe zwiększanie głośności bez przyspieszania.","steps":["Zagraj osiem pustych strun cicho przy 60 BPM.","Powtórz średnio głośno, zachowując ten sam ruch rytmiczny.","Na motywie 0–1–3–1 zrób narastanie, a potem wyciszenie."],"example":"p → mp → mf → mp → p","criteria":["Zagraj motyw z wyraźną zmianą dynamiki.","Tempo pozostaje stałe w obu kierunkach zmiany głośności."],"mistake":"Głośniej nie znaczy szybciej ani bardziej sztywno.","source":"technique","prerequisites":["ch-03-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-03-3","chapter":3,"order":3,"title":"Naprzemienne i–m","category":"Technika","theory":"Naprzemienna praca palców rozkłada wysiłek przy melodii. Zacznij od jednej struny, a dopiero potem dodaj jej zmiany.","steps":["Na pustej strunie 1 zagraj osiem ćwierćnut i–m przy 60 BPM.","Zagraj po cztery dźwięki na strunach 1, 2 i 3.","Dodaj progi 0–1–3–1 na pierwszej strunie."],"example":"i m i m | i m i m","criteria":["Zagraj trzy cykle zmiany strun bez powtarzania palca.","Utrzymaj równą głośność i oraz m."],"mistake":"Nie wymuszaj szybkości kosztem poprawnego przeplatania palców.","source":"technique","prerequisites":["ch-03-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-03-4","chapter":3,"order":4,"title":"Twój pierwszy riff","category":"Repertuar","theory":"Riff jest powracającym motywem rytmiczno-melodycznym. Ten autorski przykład łączy dwie struny; wszystkie dźwięki są ćwierćnutami.","steps":["Zagraj strunę 6 progi 0–3, następnie strunę 5 progi 0–2.","W drugim takcie wróć: struna 5 progi 2–0 i struna 6 progi 3–0.","Połącz takty przy 60 BPM i powtórz cztery razy."],"example":"| E G A B | B A G E |","criteria":["Zagraj cztery powtórzenia bez zgubienia struny.","Zachowaj tę samą długość wszystkich dźwięków."],"mistake":"Przy przejściu na nową strunę nie dodawaj pauzy.","source":"beginner","prerequisites":["ch-03-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-03-5","chapter":3,"order":5,"title":"Pierwsze nuty na pięciolinii","category":"Teoria","theory":"W kluczu wiolinowym linie od dołu to E–G–B–D–F, a pola F–A–C–E. Zapis gitarowy brzmi oktawę niżej niż zapisano. Tabulatura mówi gdzie grać, nuty także jaki dźwięk i rytm.","steps":["W lekcji źródłowej obejrzyj klucz wiolinowy i położenie nut.","Zlokalizuj E, F, G na pierwszej strunie: 0–1–3.","Narysuj nuty E na górnym polu, F na górnej linii i G nad nią."],"example":"Struna 1: E (0) · F (1) · G (3)","criteria":["Pokaż E, F i G na strunie oraz na pięciolinii.","Rozróżnij główkę nuty, laskę i kreskę taktową."],"mistake":"Pamiętaj o gitarowej transpozycji oktawowej; nie zmieniaj przez nią chwytu.","source":"theory","prerequisites":["ch-03-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-03-6","chapter":3,"order":6,"title":"Powtórz ze słuchu","category":"Słuch","theory":"Zanim szukasz dźwięku na gryfie, spróbuj go zaśpiewać. Najpierw rozpoznaj kierunek melodii, a dopiero później dokładny próg.","steps":["W warsztacie odsłuchaj dwa dźwięki i określ kierunek.","Zagraj E–F–G na strunie 1, odłóż rękę i zaśpiewaj motyw.","Wybierz trzy dźwięki znanej melodii i znajdź je bez tabulatury."],"example":"W górę: E–F–G   w dół: G–F–E","criteria":["Poprawnie rozpoznaj kierunek w 8 z 10 prób.","Odtwórz krótki motyw po zaśpiewaniu."],"mistake":"Nie szukaj losowo po całym gryfie; ogranicz się do jednej struny.","source":"ear","prerequisites":["ch-03-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-03-7","chapter":3,"order":7,"title":"Połącz akord z melodią","category":"Improwizacja","theory":"Melodia może odpowiedzieć na akord w pozostawionej przestrzeni. Nie trzeba grać obu rzeczy jednocześnie.","steps":["Zagraj Em na pierwszym pulsie i pozostaw go na drugi.","Na pulsach 3 i 4 zagraj G–E na pierwszej strunie (3–0).","W następnym takcie odpowiedz E–G; powtarzaj przy 50 BPM."],"example":"| Em – G E | Em – E G |","criteria":["Zagraj osiem taktów bez naruszenia pulsu.","Wymyśl drugą odpowiedź z tych samych dźwięków."],"mistake":"Nie zapełniaj wszystkich przerw; pauza należy do frazy.","source":"beginner","prerequisites":["ch-03-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-03-1","chapter":3,"order":8,"title":"Szesnastki bez pośpiechu","category":"Rytm","theory":"Cztery szesnastki mieszczą się w jednym pulsie ćwierćnutowym. Wolne tempo pozwala usłyszeć równość podziału.","steps":["Ustaw 40 BPM i powiedz cztery równe sylaby na klik.","Zagraj na pustej strunie 1 cztery dźwięki i–m na puls.","Przeplataj takt ćwierćnut, ósemek i szesnastek bez zmiany metronomu."],"example":"Na jeden klik: 1 dźwięk → 2 dźwięki → 4 dźwięki.","criteria":["Wykonaj cztery cykle trzech podziałów.","Każdy kolejny takt zaczyna się razem z pulsem."],"mistake":"Nie przyspieszaj całego pulsu, gdy zwiększa się liczba nut.","source":"meter","prerequisites":["ch-03-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-03-2","chapter":3,"order":9,"title":"Triole i metrum 6/8","category":"Rytm","theory":"W 6/8 zwykle czujesz dwa duże pulsy, każdy z trzema ósemkami. To inne grupowanie niż trzy pulsy po dwie ósemki w 3/4.","steps":["Policz 1–2–3, 4–5–6, akcentując 1 i 4.","Na Em zagraj sześć pojedynczych strun, grupując je w dwa pulsy.","Porównaj z 3/4, akcentując 1, 3 i 5 w tym samym szeregu sześciu ósemek."],"example":"6/8: RAZ dwa trzy CZTERY pięć sześć.","criteria":["Zagraj osiem taktów 6/8 z dwoma akcentami.","Usłysz różnicę względem trzech grup po dwie."],"mistake":"BPM musi określać, czy klika ósemka, czy duży puls. Zapisz to w notatce.","source":"meter","prerequisites":["deep-03-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-03-3","chapter":3,"order":10,"title":"Przedtakt: wejście przed jedynką","category":"Rytm","theory":"Melodia może zacząć się przed pierwszym pełnym taktem. Wtedy jej pierwszy dźwięk nie jest automatycznie pierwszym pulsem.","steps":["Odlicz 1–2–3–4, zagraj E na 4, następnie G na kolejnym 1.","Powtórz, zostawiając dwa pełne takty między wejściami.","Znajdź przedtakt w wybranej melodii i zaznacz go w notatce."],"example":"… 1 2 3 E | G — — — |","criteria":["Wejdź poprawnie pięć razy po pełnym odliczeniu.","Nie dodajesz dodatkowego pulsu przed pierwszym pełnym taktem."],"mistake":"Nie licz od nowa od 1 przy każdym usłyszanym początku frazy.","source":"meter","prerequisites":["deep-03-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-03-4","chapter":3,"order":11,"title":"Nuty na trzech górnych strunach","category":"Teoria","theory":"Czytanie zaczyna się od małego obszaru gryfu. Dźwięk powinien łączyć nazwę, zapis i miejsce, a nie tylko liczbę progu.","steps":["Znajdź E F G na strunie 1, B C D na 2 i G A na 3.","Zapisz po cztery nuty w kluczu wiolinowym, korzystając z lekcji o pięciolinii.","Następnego dnia czytaj je w innej kolejności i graj bez dopisywania tabulatury."],"example":"1: 0 1 3 · 2: 0 1 3 · 3: 0 2.","criteria":["Odczytaj osiem z dziesięciu losowych nut w tym zakresie.","Zagraj czteronutowy zapis bez patrzenia na tabulaturę."],"mistake":"Ten sam dźwięk może mieć kilka miejsc na gryfie. Tu celowo ograniczamy pozycję.","source":"theory","prerequisites":["deep-03-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-03-5","chapter":3,"order":12,"title":"Akcent zmienia charakter riffu","category":"Rytm","theory":"Riff może mieć te same wysokości i zupełnie inny charakter, gdy przesuniesz akcent. Puls nadal pozostaje stały.","steps":["Zagraj osiem równych E naprzemiennie i–m.","W pierwszej wersji zaakcentuj pierwszy i piąty dźwięk, w drugiej trzeci i siódmy.","Przenieś oba warianty na motyw E–G–A–G, powtarzany ósemkami."],"example":"Ósemki: >E G A G >E G A G; potem E G >A G E G >A G.","criteria":["Zagraj po cztery takty obu wersji.","Akcent jest głośniejszy, ale nie dłuższy."],"mistake":"Nie zatrzymuj palca przed akcentem, bo rozciągniesz rytm.","source":"technique","prerequisites":["deep-03-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-03-6","chapter":3,"order":13,"title":"Łączenie riffu z akompaniamentem","category":"Repertuar","theory":"Najtrudniejszy punkt piosenki bywa między sekcjami. Ćwiczenie samego riffu nie przygotowuje ruchu do akordu.","steps":["Wybierz riff z repertuaru lub własny E–G–A–G.","Zagraj dwa takty riffu, potem dwa takty Em ćwierćnutami.","Ćwicz osobno ostatni puls riffu i pierwszy akord, a następnie połącz cztery obiegi."],"example":"Riff 2 takty → Em 2 takty → powrót bez pauzy technicznej.","criteria":["Zagraj cztery obiegi przy 55 BPM.","Potrafisz rozpocząć także od części akordowej."],"mistake":"Pauza muzyczna jest zaplanowana; przerwa na szukanie chwytu nie jest.","source":"marty","prerequisites":["deep-03-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-03-8","chapter":3,"order":14,"title":"Wyzwanie: rytm i motyw","category":"Repertuar","theory":"Utwór nabiera charakteru, gdy wraca rozpoznawalny motyw. Wykorzystaj poznaną progresję i krótką odpowiedź melodyczną.","steps":["Zagraj cztery takty Em–Am–C–Em z prostym biciem.","Dodaj cztery takty naprzemiennie Em i motywu E–G–E.","Połącz formę, utrzymując 60 BPM i świadomą dynamikę."],"example":"A: | Em | Am | C | Em |  B: | Em | E G E – | Em | E G E – |","criteria":["Zagraj całą formę A–B dwukrotnie.","Motyw jest rozpoznawalny, a przejście nie zatrzymuje rytmu."],"mistake":"Nie wprowadzaj wielu ozdobników naraz; jeden motyw wystarczy.","source":"beginner","prerequisites":["deep-03-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-03","chapter":3,"order":15,"title":"Scena 3: Riff albo pełny groove","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-03-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[5,12],"songChoices":["song-10","rep-come","rep-wish-intro"]},{"id":"side-03-1","chapter":3,"order":1,"title":"Mały walc","category":"Repertuar","theory":"Walc opiera się na grupach po trzy. Ten autorski akompaniament można później rozwinąć w melodię.","steps":["Ustaw akcent metronomu co trzy pulsy przy 60 BPM.","Na Am zagraj bas na 1 i górne struny na 2–3.","Zmieniaj Am–E–Am–E, po dwa takty."],"example":"| Am | Am | E | E | × 2 w 3/4","criteria":["Zagraj osiem taktów z rozpoznawalnym pierwszym pulsem."],"mistake":"Nie dodawaj czwartego uderzenia przed zmianą.","source":"classical","prerequisites":["ch-03-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-03-2","chapter":3,"order":2,"title":"Melodia z pamięci","category":"Słuch","theory":"Znany motyw łatwiej odnaleźć, gdy potrafisz go zanucić.","steps":["Zanuć początek dowolnej tradycyjnej melodii.","Znajdź pierwszy dźwięk w wygodnym miejscu.","Odtwórz kolejne trzy dźwięki na jednej strunie."],"example":"Głos → jeden dźwięk → kierunek → fraza","criteria":["Odtwórz cztery dźwięki bez gotowego zapisu."],"mistake":"Nie zaczynaj od wyszukiwania tabulatury.","source":"ear","prerequisites":["ch-03-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Słuch i czytanie"},{"id":"branch-03-1","chapter":3,"order":3,"title":"Rytm shuffle na jednym akordzie","category":"Rytm","theory":"Podział długi–krótki wyrasta z trioli. Zachowaj wspólny puls także przy zmianie z prostych ósemek.","steps":["Powiedz tri-o-la na każdy klik przy 50 BPM.","Zagraj pierwszy i trzeci element na E7.","Przeplataj dwa takty shuffle i dwa takty prostych ósemek."],"example":"Tri (cisza) la → tri (cisza) la.","criteria":["Wykonaj cztery przejścia między podziałami bez zmiany pulsu."],"mistake":"Nie graj przypadkowo nierównych ósemek zamiast świadomej trioli.","source":"meter","prerequisites":["ch-03-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Blues"},{"id":"branch-03-2","chapter":3,"order":4,"title":"Walc: bas i dwa akordy","category":"Rytm","theory":"W prostym walcu bas na 1 pomaga usłyszeć początek taktu, a lżejsze akordy wypełniają 2 i 3.","steps":["Na Am zagraj kciukiem strunę 5 na 1.","Na 2 i 3 szarp razem struny 3–2–1.","Zmieniaj Am–Em co dwa takty i graj cicho na 2 oraz 3."],"example":"1 bas · 2 akord · 3 akord.","criteria":["Zagraj osiem taktów 3/4 bez dodawania czwartego pulsu."],"mistake":"Nie akcentuj jednakowo wszystkich trzech części taktu.","source":"meter","prerequisites":["ch-03-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Klasyka"},{"id":"branch-03-3","chapter":3,"order":5,"title":"Dyktando czterech taktów rytmu","category":"Słuch","theory":"Zapis rytmu może zacząć się od słów i kresek. Ważne, aby zapis dawał się wykonać po przerwie.","steps":["Wymyśl cztery takty z ćwierćnut, ósemek i pauz.","Zapisz pod każdym numer pulsu i „i”.","Po przerwie wyklaszcz zapis, a potem zagraj go na E."],"example":"1 i 2 i 3 i 4 i — siatka ośmiu miejsc.","criteria":["Odtwórz swój zapis następnego dnia bez dopowiadania brakującego pulsu."],"mistake":"Nie pomijaj pauz w zapisie tylko dlatego, że nie słychać w nich nuty.","source":"meter","prerequisites":["ch-03-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,4],"branch":"Słuch i czytanie"},{"id":"ch-04-1","chapter":4,"order":1,"title":"Półton i ton","category":"Teoria","theory":"Jeden próg to półton, dwa progi to cały ton. Między E–F i B–C jest półton, między pozostałymi sąsiadującymi literami naturalnymi cały ton.","steps":["Na strunie 1 zagraj E–F na progach 0–1.","Zagraj F–G na progach 1–3 i porównaj odległość.","Znajdź B–C na strunie 2: 0–1."],"example":"E–F: 1 próg   F–G: 2 progi   B–C: 1 próg","criteria":["Pokaż trzy przykłady półtonu i całego tonu.","Wyjaśnij, dlaczego E–F nie wymaga dwóch progów."],"mistake":"Nie zakładaj, że każda kolejna litera to cały ton.","source":"theory","prerequisites":["rep-03"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-04-2","chapter":4,"order":2,"title":"Mapa dźwięków do XII progu","category":"Teoria","theory":"Po dwunastu półtonach wraca ta sama nazwa dźwięku o oktawę wyżej. Najpierw poznaj struny 6 i 5 — będą punktami orientacyjnymi dla akordów.","steps":["Nazwij E–F–G–A–B–C–D–E na strunie 6: 0–1–3–5–7–8–10–12.","Znajdź A–B–C–D–E–F–G–A na strunie 5: 0–2–3–5–7–8–10–12.","W warsztacie ukryj nazwy i sprawdź dziesięć losowych progów."],"example":"Struna 6: E F F♯ G G♯ A B♭ B C C♯ D E♭ E","criteria":["Nazwij 8 z 10 losowanych dźwięków na strunach 5 i 6.","Znajdź oktawę dowolnego dźwięku na tej samej strunie."],"mistake":"Ucz się kilku punktów orientacyjnych, nie tylko mechanicznego liczenia od zera.","source":"theory","prerequisites":["ch-04-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-04-3","chapter":4,"order":3,"title":"Usłysz i znajdź oktawę","category":"Słuch","theory":"Oktawa ma 12 półtonów. Dwa dźwięki oktawy mają tę samą nazwę, ale różną wysokość. Śpiew może być w wygodnej dla Ciebie oktawie.","steps":["Porównaj puste struny 6 i 1: to E oddalone o dwie oktawy.","Zagraj A na strunie 5 próg 0 i na strunie 3 próg 2.","Zaśpiewaj oba dźwięki, potem znajdź C na 5/3 i 3/5."],"example":"A2 → A3: 5/0 → 3/2   C3 → C4: 5/3 → 3/5","criteria":["Pokaż trzy pary dźwięków odległych o oktawę.","Rozpoznaj oktawę w 8 z 10 prób quizu interwałów."],"mistake":"Schemat między strunami zmienia się przy przekraczaniu struny B.","source":"ear","prerequisites":["ch-04-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-04-4","chapter":4,"order":4,"title":"Tercje, kwarty i kwinty","category":"Teoria","theory":"Tercja mała ma 3 półtony, wielka 4, kwarta czysta 5, kwinta czysta 7. Nazwa liczbowa wynika także z liter: C–E jest tercją, C–F kwartą.","steps":["Na strunie 5 od C (próg 3) zagraj E♭ (6), E (7), F (8), G (10).","Posłuchaj każdej pary w warsztacie i zaśpiewaj odpowiedź.","Ułóż melodię C–E–G–E, używając poznanych odległości."],"example":"C–E♭ = 3 · C–E = 4 · C–F = 5 · C–G = 7 półtonów","criteria":["Pokaż cztery interwały od C.","Rozpoznaj 8 z 10 przykładów przy ograniczonym zestawie interwałów."],"mistake":"Nie nazywaj interwału wyłącznie po odległości palców bez sprawdzenia liter.","source":"theory","prerequisites":["ch-04-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-04-5","chapter":4,"order":5,"title":"Zbuduj skalę durową","category":"Teoria","theory":"Skala durowa powstaje z układu ton–ton–półton–ton–ton–ton–półton. W C-dur są tylko dźwięki naturalne.","steps":["Zagraj C–D–E na strunie 5 progi 3–5–7.","Kontynuuj F–G–A–B–C na progach 8–10–12–14–15, jeśli dostępne; inaczej użyj pozycji otwartej.","Zagraj pozycję otwartą z przykładu i zaśpiewaj skalę."],"example":"5:3 | 4:0,2,3 | 3:0,2 | 2:0,1 → C D E F G A B C","criteria":["Zagraj skalę w górę i w dół trzy razy przy 60 BPM.","Wskaż półtony E–F i B–C."],"mistake":"Nie ćwicz jedynie kształtu; wypowiadaj nazwy dźwięków.","source":"theory","prerequisites":["ch-04-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-04-6","chapter":4,"order":6,"title":"Skąd biorą się akordy","category":"Teoria","theory":"Triada bierze co drugi dźwięk: stopnie 1, 3 i 5. C-dur to C–E–G, a a-moll to A–C–E. Zmiana tercji zmienia tryb akordu.","steps":["W skali C-dur wybierz dźwięki C, E, G.","Zagraj je osobno, potem chwytem C.","Powtórz dla A–C–E i Am; wskaż tercję obu akordów."],"example":"C: 1–3–5 = C E G   Am: 1–♭3–5 = A C E","criteria":["Zbuduj triady C, G i Am na kartce.","Znajdź ich składniki w znanych chwytach."],"mistake":"Trzy różne dźwięki mogą powtarzać się na sześciu strunach akordu.","source":"theory","prerequisites":["ch-04-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-04-7","chapter":4,"order":7,"title":"Tonacja i dom melodii","category":"Słuch","theory":"Tonika jest punktem odniesienia. Melodia nie musi zaczynać się od toniki, ale jej powrót często daje poczucie zakończenia.","steps":["Zagraj progresję C–Fmaj7–G–C, używając Fmaj7 xx3210.","Zaśpiewaj C i porównaj je z B nad ostatnim akordem.","Ułóż cztery dźwięki z C-dur kończące się na C."],"example":"C – D – B – C: napięcie i powrót","criteria":["Zaśpiewaj tonikę po progresji.","Zagraj dwie różne frazy kończące się na C."],"mistake":"Nie zakładaj, że pierwszy akord każdej piosenki zawsze wskazuje tonację.","source":"ear","prerequisites":["ch-04-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-04-1","chapter":4,"order":8,"title":"B, H i dźwięki enharmoniczne","category":"Teoria","theory":"W tej aplikacji B oznacza polskie H, a B♭ polskie B. C♯ i D♭ na gitarze temperowanej mają ten sam próg, ale różne funkcje w zapisie.","steps":["Na strunie 2 zagraj B na 0 i C na 1.","Na strunie 5 znajdź B♭ na 1 oraz B na 2.","Zapisz skalę D-dur z C♯, nie D♭; każda litera pojawia się raz."],"example":"Międzynarodowe: A B♭ B C · polskie: A B H C.","criteria":["Przetłumacz pięć nazw B/H/B♭ bez pomyłki.","Pokaż na gryfie jedną parę enharmoniczną."],"mistake":"Nie nazywaj C♯ i D♭ dwiema różnymi wysokościami w standardowym stroju.","source":"major","prerequisites":["ch-04-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-04-2","chapter":4,"order":9,"title":"Sekundy, seksty i septymy","category":"Słuch","theory":"Rozszerz zestaw interwałów dopiero po tercjach i kwintach. Seksta i septyma to większy skok, ale nadal można go usłyszeć oraz odnaleźć.","steps":["Od C na 5/3 zagraj D na 4/0, A na 3/2 i B na 2/0.","Porównaj 2, 9 i 11 półtonów w warsztacie.","Zaśpiewaj odpowiedź i ułóż trzy frazy, każdą z innym skokiem."],"example":"C–D: sekunda wielka; C–A: seksta wielka; C–B: septyma wielka.","criteria":["Rozpoznaj 8/10 prób z ograniczonego zestawu.","Znajdź każdy z trzech interwałów od nowej podstawy."],"mistake":"Najpierw określ liczbę liter, potem jakość interwału.","source":"intervals","prerequisites":["deep-04-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-04-3","chapter":4,"order":10,"title":"Interwał harmoniczny i przewrót","category":"Teoria","theory":"Interwał melodyczny brzmi kolejno, harmoniczny jednocześnie. Przeniesienie dolnego dźwięku oktawę wyżej zmienia interwał w jego przewrót.","steps":["Zagraj C na 3/5 oraz E na 2/5 kolejno i razem.","Przenieś C na 1/8: para E–C tworzy sekstę małą.","Porównaj F–B oraz B–F i nazwij odległości."],"example":"Tercja wielka C–E → seksta mała E–C; liczby sumują się do 9.","criteria":["Zagraj i nazwij przewroty tercji oraz kwinty.","Rozróżnij słuchem granie kolejno od współbrzmienia."],"mistake":"Przewrót interwału nie jest zmianą trybu akordu.","source":"intervals","prerequisites":["deep-04-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-04-4","chapter":4,"order":11,"title":"Ta sama nuta w kilku miejscach","category":"Technika","theory":"Na gitarze jedna wysokość ma kilka palcowań. Wybór pozycji wpływa na barwę oraz łatwość następnego ruchu.","steps":["Znajdź E4 na 1/0, 2/5 i 3/9.","Zagraj krótką melodię E–F–G na strunie 1, potem na 2: progi 5–6–8.","Porównaj barwę i wybierz palcowanie ułatwiające powrót do C na strunie 2."],"example":"E4: 1/0 = 2/5 = 3/9; ta sama wysokość, inna struna.","criteria":["Zagraj motyw w dwóch miejscach bez zmiany melodii.","Uzasadnij jeden wybór palcowania."],"mistake":"Nie myl tej samej nazwy w innej oktawie z tą samą wysokością.","source":"technique","prerequisites":["deep-04-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-04-5","chapter":4,"order":12,"title":"Znaki przykluczowe: G i D","category":"Teoria","theory":"Znaki przy kluczu obowiązują przez cały utwór, dopóki nie zostaną zmienione. Budowa skali pozwala je sprawdzić bez zgadywania.","steps":["Zbuduj G-dur od wzoru tonów i półtonów; zaznacz F♯.","Zbuduj D-dur, zaznacz F♯ i C♯.","Zagraj po cztery dźwięki każdej skali w wygodnej pozycji i zaśpiewaj tonikę."],"example":"G A B C D E F♯ G · D E F♯ G A B C♯ D.","criteria":["Zapisz obie skale bez pominięcia znaku.","Znajdź F♯ i C♯ w dwóch miejscach gryfu."],"mistake":"Nie przenoś automatycznie wszystkich pustych strun do dowolnej tonacji.","source":"major","prerequisites":["deep-04-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-04-6","chapter":4,"order":13,"title":"Funkcje I, IV i V w piosence","category":"Teoria","theory":"Cyfry rzymskie opisują stopień, na którym budujesz akord. W tonacji durowej I, IV i V są durowe i pozwalają usłyszeć ruch od toniki do napięcia i powrotu.","steps":["Zagraj C–Fmaj7–G–C i nazwij podstawy C, F, G.","Porównaj z G–C–D–G, zachowując czas trwania akordów.","W wybranej piosence zaznacz tonikę i dominantę, jeśli występują."],"example":"C: I=C, IV=F, V=G · G: I=G, IV=C, V=D.","criteria":["Zagraj ten sam ruch w dwóch tonacjach.","Wyjaśnij, że Fmaj7 jest tu łatwym wariantem IV z dodaną septymą."],"mistake":"Pierwszy akord utworu nie musi być toniką. Sprawdź zakończenie i brzmienie.","source":"cadences","prerequisites":["deep-04-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"ch-04-8","chapter":4,"order":14,"title":"Wyzwanie: melodia z mapy","category":"Improwizacja","theory":"Teraz nazwy, interwały i słuch łączą się w jedną umiejętność. Stwórz własną krótką melodię w C-dur.","steps":["Wybierz cztery dźwięki ze skali i zapisz ich nazwy.","Ułóż cztery takty przy 60 BPM, z co najmniej jedną pauzą.","Zakończ na C i pokaż jedną tercję oraz jeden ruch sekundowy."],"example":"Przykładowy początek: | C E G – | E D C – |; dokończ po swojemu.","criteria":["Zagraj własne cztery takty dwukrotnie.","Nazwij użyte dźwięki oraz dwa interwały."],"mistake":"Nie losuj palcowania przy każdym powtórzeniu; utrwal własny pomysł.","source":"theory","prerequisites":["deep-04-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-04","chapter":4,"order":15,"title":"Scena 4: Zagraj i wyjaśnij melodię","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-04-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[10,25],"songChoices":["rep-greensleeves-melody","rep-birthday","rep-ode-transfer"]},{"id":"side-04-1","chapter":4,"order":1,"title":"Koło kwint w praktyce","category":"Teoria","theory":"Kolejne tonacje po kwintach dodają krzyżyki. C nie ma znaków, G ma F♯, D ma F♯ i C♯.","steps":["Zbuduj skalę G-dur według wzoru tonów i półtonów.","Zapisz różnicę względem C-dur.","Zagraj G–A–B–C–D–E–F♯–G w wybranej pozycji."],"example":"C → G → D; 0 → 1 → 2 krzyżyki","criteria":["Nazwij znaki C, G i D-dur oraz zagraj G-dur."],"mistake":"Nie myl kolejności kwint z kolejnością dźwięków skali.","source":"theory","prerequisites":["ch-04-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-04-2","chapter":4,"order":2,"title":"Interwał od nowego dźwięku","category":"Słuch","theory":"Rozpoznanie interwału powinno działać także po zmianie wysokości początkowej.","steps":["W quizie wybierz tercję małą, wielką i kwintę.","Odsłuchaj dziesięć losowych par.","Zaśpiewaj odpowiedź przed sprawdzeniem."],"example":"3, 4 lub 7 półtonów od różnych podstaw","criteria":["Uzyskaj 8/10 w dwóch seriach."],"mistake":"Nie zapamiętuj wyłącznie absolutnej wysokości jednego przykładu.","source":"ear","prerequisites":["ch-04-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Słuch i czytanie"},{"id":"branch-04-1","chapter":4,"order":3,"title":"Przewroty triady na jednej strunie","category":"Teoria","theory":"Przewrót zmienia najniższy składnik, zachowując zestaw dźwięków. Możesz najpierw poznać go jako melodię.","steps":["Zagraj kolejno C–E–G.","Przenieś C oktawę wyżej i zagraj E–G–C.","Zagraj G–C–E, porównując wszystkie trzy układy."],"example":"C E G → E G C → G C E.","criteria":["Nazwij podstawową postać oraz dwa przewroty."],"mistake":"Nie zmieniaj C-dur w inny akord tylko dlatego, że zaczyna się od E.","source":"inversions","prerequisites":["ch-04-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Jazz i bossa"},{"id":"branch-04-2","chapter":4,"order":4,"title":"Interwały w dół","category":"Słuch","theory":"Rozpoznawanie skoku w dół nie zawsze przenosi się automatycznie z ćwiczeń w górę. Ćwicz oba kierunki osobno.","steps":["Zagraj G–E, G–C oraz E–C.","Policz półtony i nazwij interwały.","Zaśpiewaj każdą parę od innego wygodnego dźwięku, potem sprawdź na gryfie."],"example":"G→E: tercja mała w dół; G→C: kwinta czysta w dół.","criteria":["Odtwórz trzy różne skoki w dół po ich usłyszeniu."],"mistake":"Kierunek nie zmienia liczby półtonów tej samej pary wysokości.","source":"intervals","prerequisites":["ch-04-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Słuch i czytanie"},{"id":"branch-04-3","chapter":4,"order":5,"title":"Czytanie bez zatrzymania","category":"Technika","theory":"Czytanie a vista wymaga łatwiejszego materiału niż utwór ćwiczony tygodniami. Patrz odrobinę przed aktualny dźwięk.","steps":["Napisz osiem prostych taktów nut na strunach 1–3.","Odłóż zapis do następnego dnia, przejrzyj rytm przed startem.","Zagraj raz przy 40 BPM i nie wracaj do pomyłek do końca próby."],"example":"Przejrzyj → odlicz → czytaj → dopiero potem popraw.","criteria":["Przejdź cały zapis z zachowaniem liczby pulsów."],"mistake":"Nie wybieraj do czytania utworu, który jest na granicy Twojej techniki.","source":"classical","prerequisites":["ch-04-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Klasyka"},{"id":"ch-05-1","chapter":5,"order":1,"title":"Pięć dźwięków, wiele możliwości","category":"Teoria","theory":"Pentatonika a-moll zawiera A, C, D, E, G. Mniejszy zestaw pozwala skupić się na rytmie, ale żaden kształt nie gwarantuje dobrego frazowania.","steps":["Zagraj A i C na strunie 5 (0,3), D i E na 4 (0,2), G i A na 3 (0,2).","Zagraj w górę i w dół, nazywając dźwięki.","Wybierz tylko A, C i E i ułóż krótką odpowiedź."],"example":"A C D E G A = 5/0,3 · 4/0,2 · 3/0,2","criteria":["Zagraj skalę bez pomijania dźwięków.","Zbuduj trzy różne motywy z trzech dźwięków."],"mistake":"Nie zaczynaj każdej improwizacji od przebiegu całej skali.","source":"beginner","prerequisites":["rep-04"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-05-2","chapter":5,"order":2,"title":"Rytm na jednym dźwięku","category":"Improwizacja","theory":"Ciekawa fraza nie wymaga wielu wysokości. Zmieniaj długość dźwięków, akcenty i ciszę.","steps":["Na A (struna 3 próg 2) graj cztery ćwierćnuty przy 60 BPM.","W następnym takcie zagraj dwie ósemki, ćwierćnutę i półnutową pauzę.","Stwórz jeszcze dwa takty o innych rytmach."],"example":"| A A A A | A-A A pauza pauza |","criteria":["Ułóż cztery rozpoznawalnie różne rytmy.","Każdy rytm mieści się w takcie 4/4."],"mistake":"Nie dodawaj nowych dźwięków, dopóki rytm sam nie brzmi ciekawie.","source":"beginner","prerequisites":["ch-05-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-05-3","chapter":5,"order":3,"title":"Pytanie i odpowiedź","category":"Improwizacja","theory":"Call and response to rozmowa fraz. Pytanie pozostawia otwartą myśl, a odpowiedź może wrócić do dźwięku podstawowego.","steps":["Zagraj dwutaktowe pytanie z A–C–D, kończąc na D.","Zostaw jeden puls ciszy.","Odpowiedz dwoma taktami z E–C–A, kończąc na A."],"example":"Pytanie: A C D –   odpowiedź: E C A –","criteria":["Zagraj trzy różne pary pytań i odpowiedzi.","W każdej parze zostaw słyszalną przestrzeń."],"mistake":"Nie graj obu fraz identycznie bez zmiany zakończenia.","source":"beginner","prerequisites":["ch-05-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-05-4","chapter":5,"order":4,"title":"Rozwijaj motyw","category":"Improwizacja","theory":"Motyw spaja solo. Możesz zachować rytm i zmienić ostatni dźwięk albo powtórzyć dźwięki z innym akcentem.","steps":["Wymyśl motyw A–C–E z jedną pauzą.","Powtórz go dwa razy bez zmian.","Zmień tylko zakończenie na G, a potem wróć do A."],"example":"A C E – → A C G – → A C A –","criteria":["Zagraj motyw i dwie świadome wariacje.","Potrafisz wskazać, co zmieniło się w każdej wariacji."],"mistake":"Zbyt wiele zmian naraz sprawia, że motyw przestaje być rozpoznawalny.","source":"intermediate","prerequisites":["ch-05-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-05-5","chapter":5,"order":5,"title":"Dźwięki akordu jako cel","category":"Teoria","theory":"Nad Am dźwięki A, C i E należą do akordu. Kończenie na nich pomaga połączyć melodię z harmonią. Pozostałe dźwięki mogą prowadzić do celu.","steps":["Zagraj Am i wsłuchaj się w A–C–E.","Ułóż frazę D–C i drugą G–E.","Na zmianę graj akord oraz odpowiedź, kończąc na składniku Am."],"example":"D → C, G → E, C → A nad Am","criteria":["Zagraj trzy frazy z różnymi dźwiękami docelowymi.","Nazwij składnik akordu na końcu każdej frazy."],"mistake":"Nie traktuj wszystkich dźwięków skali jako równorzędnych zakończeń.","source":"theory","prerequisites":["ch-05-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-05-6","chapter":5,"order":6,"title":"Dłuższe dźwięki i oddech","category":"Technika","theory":"Długość i wyciszenie dźwięku są równie ważne jak jego początek. Celowo kończ dźwięk lekkim dotknięciem struny.","steps":["Na A zagraj półnutę, potem dwie ćwierćnuty ciszy.","Powtórz na C i E, tłumiąc dokładnie na trzecim pulsie.","Wpleć ten gest w dwutaktową frazę."],"example":"| A — cisza cisza | C E A — |","criteria":["Utrzymaj osiem taktów z kontrolowaną ciszą.","Wyciszenie nie dodaje głośnego przypadkowego dźwięku."],"mistake":"Nie odrywaj lewej dłoni gwałtownie: może powstać niechciany pull-off.","source":"technique","prerequisites":["ch-05-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-05-7","chapter":5,"order":7,"title":"Najpierw zaśpiewaj","category":"Słuch","theory":"Śpiewanie przed graniem pomaga usłyszeć pomysł zamiast poruszać palcami nawykowo. Wysokość głosu nie musi być idealna, ważna jest intencja.","steps":["Zagraj A jako punkt odniesienia.","Zaśpiewaj trzydźwiękowy motyw z pentatoniki.","Znajdź go na gitarze, sprawdź i powtórz pięć różnych pomysłów."],"example":"Usłysz → zaśpiewaj → znajdź → zagraj","criteria":["Odtwórz trzy z pięciu własnych motywów zgodnie z zamiarem.","Zapisz jeden motyw nazwami dźwięków."],"mistake":"Nie oceniaj barwy głosu; używaj go jako narzędzia słuchowego.","source":"ear","prerequisites":["ch-05-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-05-1","chapter":5,"order":8,"title":"Pentatonika durowa i molowa","category":"Teoria","theory":"C-dur i a-moll mają wspólne dźwięki pentatoniki, ale inne centrum. Ten sam zbiór nie oznacza tego samego wrażenia zakończenia.","steps":["Zagraj C–D–E–G–A nad akordem C.","Zagraj A–C–D–E–G nad Am.","Ułóż dwie frazy z tych samych dźwięków: jedną kończąc na C, drugą na A."],"example":"C-dur: 1 2 3 5 6 · a-moll: 1 ♭3 4 5 ♭7.","criteria":["Wykonaj dwie frazy o różnych centrach.","Zaśpiewaj tonikę po każdym akordzie."],"mistake":"Nie przesuwaj tylko kształtu, nie wiedząc, gdzie jest tonika.","source":"major","prerequisites":["ch-05-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-05-2","chapter":5,"order":9,"title":"Ograniczenie: tylko rytm i pauza","category":"Improwizacja","theory":"Ograniczenia pozwalają ocenić jeden element muzyki. Przy trzech wysokościach łatwiej usłyszeć, czy fraza rzeczywiście coś opowiada.","steps":["Wybierz A, C i E; ustaw 60 BPM.","Zagraj cztery takty, w każdym zostaw cały puls ciszy.","Zagraj kolejne cztery, zachowując rytm, ale zmieniając kolejność dźwięków."],"example":"A – C E | pauza A — —; – oznacza podtrzymanie.","criteria":["Zagraj osiem taktów bez dodania czwartego dźwięku.","Potrafisz powtórzyć jeden z rytmów po zakończeniu."],"mistake":"Losowa cisza wynikająca z szukania progu nie jest zaplanowaną pauzą.","source":"ear","prerequisites":["deep-05-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-05-3","chapter":5,"order":10,"title":"Fraza rozpoczynająca się po jedynce","category":"Rytm","theory":"Solo nie musi zaczynać się razem z każdym taktem. Późniejsze wejście zostawia miejsce dla akompaniamentu.","steps":["Odlicz takt i zacznij A–C–E dopiero na 2.","W kolejnej próbie zacznij na „i” po 2, licząc ósemki.","Po każdej frazie zostaw takt ciszy i wróć w zaplanowanym miejscu."],"example":"1 i 2 [i: A] 3:C i 4:E i.","criteria":["Wykonaj po cztery wejścia obu wariantów.","Wiesz, gdzie jest 1 także podczas ciszy."],"mistake":"Nie skracaj taktu, aby kolejna fraza zaczęła się natychmiast.","source":"meter","prerequisites":["deep-05-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-05-4","chapter":5,"order":11,"title":"Przesunięcie palca: slide","category":"Technika","theory":"Slide łączy dwa dźwięki jednym ruchem po strunie. Na nylonie ważniejsze są czyste końce i rytm niż głośny szum między progami.","steps":["Zagraj A na 3/2 i przesuń palec do C na 3/5.","Wróć z C do A, nie dociskając mocniej w ruchu.","Wpleć slide w cztery takty, docierając do celu na 3."],"example":"1: A, 2: ruch, 3: C, 4: cisza.","criteria":["Traf do progu docelowego osiem razy przy 50 BPM.","Dźwięk końcowy jest czysty, bez nadmiernego napięcia."],"mistake":"Nie przyspieszaj ruchu bez określenia, na który puls ma dotrzeć cel.","source":"technique","prerequisites":["deep-05-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-05-5","chapter":5,"order":12,"title":"Dwie frazy nad dwoma akordami","category":"Improwizacja","theory":"Już dwa akordy wystarczą, aby odpowiedź zmieniała się wraz z harmonią. Nad Am wybierz C lub E, nad C wybierz E lub G.","steps":["Zagraj Am przez dwa takty, potem C przez dwa.","Po każdym akordzie zagraj krótką odpowiedź kończącą się na wybranym składniku.","Wykonaj cztery obiegi i zmień zakończenia, zachowując rytm."],"example":"Am → D–C; C → A–G.","criteria":["Każda odpowiedź kończy się na dźwięku bieżącego akordu.","Potrafisz nazwać cztery użyte zakończenia."],"mistake":"Nie oceniaj dopasowania tylko po tym, że wszystkie dźwięki pochodzą z tej samej skali.","source":"triads","prerequisites":["deep-05-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-05-6","chapter":5,"order":13,"title":"Zapamiętaj własne solo","category":"Słuch","theory":"Improwizacja może zostawić materiał do kompozycji. Wybranie i odtworzenie najlepszej frazy uczy świadomego słownika muzycznego.","steps":["Zaimprowizuj osiem taktów i wybierz najlepsze dwa.","Zapisz rytm słowami oraz nazwy dźwięków lub progi.","W następnej sesji odtwórz frazę, potem zmień tylko jedną nutę."],"example":"Pomysł → zapis → pamięć → wariacja.","criteria":["Odtwórz własną frazę w kolejnej sesji.","Pokaż oryginał i jedną rozpoznawalną wariację."],"mistake":"Nie zapisuj wyłącznie nazw nut bez ich długości.","source":"practice","prerequisites":["deep-05-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"ch-05-8","chapter":5,"order":14,"title":"Wyzwanie: minuta własnej muzyki","category":"Improwizacja","theory":"Dobre krótkie solo ma początek, rozwinięcie i zakończenie. Ogranicz materiał do pentatoniki a-moll.","steps":["Ustaw 60 BPM i zaplanuj motyw otwierający.","Graj przez 16 taktów: przedstaw motyw, rozwiń go i zostaw pauzy.","Ostatnią frazę zakończ na A, C lub E po zagraniu Am."],"example":"16 taktów 4/4 przy 60 BPM ≈ 64 sekundy","criteria":["Zagraj co najmniej minutę bez przerwania pulsu.","Użyj motywu, wariacji i przynajmniej trzech świadomych pauz."],"mistake":"Nie oceniaj solo liczbą zagranych dźwięków.","source":"beginner","prerequisites":["deep-05-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-05","chapter":5,"order":15,"title":"Scena 5: Znana piosenka, Twoja odpowiedź","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-05-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[10,25],"songChoices":["rep-horse-improv","rep-knock-improv","rep-stand-improv"]},{"id":"side-05-1","chapter":5,"order":1,"title":"Pierwsze bluesowe brzmienie","category":"Improwizacja","theory":"Dodanie E♭ do pentatoniki a-moll daje charakterystyczny dźwięk przejściowy pomiędzy D i E.","steps":["Na strunie 4 zagraj progi 0–1–2: D–E♭–E.","Połącz z A i C z pentatoniki.","Ułóż dwie krótkie frazy kończące się na A."],"example":"A C D E♭ E → C A","criteria":["Użyj E♭ jako świadomego przejścia w dwóch frazach."],"mistake":"Nie zatrzymuj każdego motywu na nowym dźwięku tylko dlatego, że jest nowy.","source":"beginner","prerequisites":["ch-05-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-05-2","chapter":5,"order":2,"title":"Solo z trzech dźwięków","category":"Improwizacja","theory":"Ograniczenie dźwięków uczy rytmu i świadomego frazowania.","steps":["Wybierz A, C i E.","Przez osiem taktów zmieniaj tylko rytm, akcent i kolejność.","Powtórz najlepszy motyw w ostatnich dwóch taktach."],"example":"Materiał: A C E; forma: 8 taktów","criteria":["Zagraj osiem taktów z przynajmniej czterema różnymi rytmami."],"mistake":"Nie dodawaj kolejnych dźwięków w trakcie tego ćwiczenia.","source":"beginner","prerequisites":["ch-05-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"branch-05-1","chapter":5,"order":3,"title":"Blue note jako przejście","category":"Improwizacja","theory":"Obniżona kwinta może zwiększać napięcie między kwartą a kwintą. Użyj jej celowo w krótkim ruchu.","steps":["Zagraj D–E♭–E na strunie 4 progach 0–1–2.","Dołącz C i A z pentatoniki.","Ułóż dwa motywy, raz przechodząc szybko przez E♭, raz zatrzymując je na chwilę."],"example":"A C D E♭ E → C A.","criteria":["Zagraj oba warianty i wskaż miejsce rozwiązania napięcia."],"mistake":"Nie dodawaj blue note do każdego taktu tylko dlatego, że ją znasz.","source":"intermediate","prerequisites":["ch-05-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Blues"},{"id":"branch-05-2","chapter":5,"order":4,"title":"Akord i odpowiedź bez podkładu","category":"Improwizacja","theory":"Na jednej gitarze można prowadzić rozmowę akordu z melodią. Cisza między nimi jest częścią aranżacji.","steps":["Zagraj Am na 1, pozwól mu wybrzmieć na 2.","Na 3 i 4 zagraj C–E.","W drugim takcie odpowiedz E–C–A, potem powtórz z nowym rytmem."],"example":"Akord → oddech → dwie nuty → odpowiedź.","criteria":["Zagraj osiem taktów z czterema różnymi odpowiedziami."],"mistake":"Nie próbuj podtrzymać pełnego chwytu, jeśli blokuje prostą melodię.","source":"triads","prerequisites":["ch-05-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Fingerstyle"},{"id":"branch-05-3","chapter":5,"order":5,"title":"Zaśpiewaj tercję akordu","category":"Słuch","theory":"Tercja mówi wiele o jakości akordu. Usłyszenie jej przed graniem pomaga celować we frazie.","steps":["Zagraj C, znajdź i zaśpiewaj E.","Zagraj Am, znajdź i zaśpiewaj C.","Powtórz dla G oraz Em, sprawdzając odpowiedź gitarą."],"example":"C→E · Am→C · G→B · Em→G.","criteria":["Traf tercję w trzech z czterech akordów po krótkim namyśle."],"mistake":"Możesz śpiewać w wygodnej oktawie; liczy się nazwa i relacja.","source":"ear","prerequisites":["ch-05-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Słuch i czytanie"},{"id":"ch-06-1","chapter":6,"order":1,"title":"Arpeggio p–i–m–a","category":"Technika","theory":"Arpeggio akompaniujące rozdziela akord na kolejne dźwięki. Pozwól im wybrzmiewać, zachowując równe odstępy.","steps":["Ułóż Am i zagraj p na 5, i na 3, m na 2, a na 1.","Powtarzaj przy 50 BPM po jednym dźwięku na puls.","Zmieniaj Am na C co dwa takty, utrzymując wzór."],"example":"Am: A A C E   palce p i m a","criteria":["Zagraj osiem taktów arpeggia bez zgubienia kolejności.","Zmiana akordu nie zatrzymuje prawej dłoni."],"mistake":"Nie przyspieszaj ostatnich trzech palców po kciuku.","source":"technique","prerequisites":["rep-05"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-06-2","chapter":6,"order":2,"title":"Kciuk idzie własną drogą","category":"Technika","theory":"Bas może utrzymywać puls, podczas gdy palce dodają odpowiedzi. Zacznij od prostych, naprzemiennych ruchów.","steps":["Na Am zagraj kciukiem strunę 5 na 1 i strunę 4 na 3.","Palcem i dodaj strunę 3 na 2 i 4.","Zagraj osiem taktów przy 60 BPM."],"example":"1: p5 · 2: i3 · 3: p4 · 4: i3","criteria":["Zachowaj równy bas przez osiem taktów.","Pozostałe palce nie usztywniają się przy ruchu kciuka."],"mistake":"Nie przyspieszaj basu, gdy dołącza palec wskazujący.","source":"technique","prerequisites":["ch-06-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-06-3","chapter":6,"order":3,"title":"Melodia ponad basem","category":"Technika","theory":"Melodia powinna pozostać słyszalna nad akompaniamentem. To ćwiczenie korzysta z E w basie i górnych dźwięków E–G.","steps":["Zagraj jednocześnie p na strunie 6 oraz a na strunie 1 próg 0.","Powtórz z górnym G na progu 3.","Zagraj bas tylko na 1, melodię E–G–E na 1–2–3."],"example":"Bas: E – – –   melodia: E G E –","criteria":["Zagraj osiem taktów z melodią głośniejszą od basu.","Bas pojawia się dokładnie na początku taktu."],"mistake":"Nie próbuj wyróżnić melodii, uderzając jednocześnie mocniej bas.","source":"technique","prerequisites":["ch-06-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-06-4","chapter":6,"order":4,"title":"Hammer-on na nylonie","category":"Technika","theory":"Hammer-on tworzy drugi dźwięk przez postawienie palca lewej dłoni bez ponownego szarpnięcia. Precyzja jest ważniejsza niż siła.","steps":["Na pierwszej strunie zagraj pustą E.","Postaw palec 1 na progu 1 tak, by zabrzmiało F.","Ćwicz pary 0h1 jako dwie ósemki przy 50 BPM z pauzą po parze."],"example":"e|–0h1––0h1––|","criteria":["Zagraj osiem par z czytelnym drugim dźwiękiem.","Nie napinaj barku ani nie zwiększaj nadmiernie nacisku."],"mistake":"Nie uderzaj palcem daleko od progu; dźwięk będzie przytłumiony.","source":"ch-06-4-source","prerequisites":["ch-06-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-06-5","chapter":6,"order":5,"title":"Pull-off pod kontrolą","category":"Technika","theory":"Pull-off uwalnia przygotowany niższy dźwięk. Delikatny ruch opuszczającego palca podtrzymuje brzmienie, ale nie powinien zaczepiać sąsiadów.","steps":["Przygotuj próg 1 na pierwszej strunie i zagraj F.","Delikatnie zwolnij palec tak, by zabrzmiała pusta E.","Zagraj osiem par 1p0, a potem połącz 0h1p0."],"example":"e|–1p0––1p0––0h1p0–|","criteria":["Osiem par ma dwa czytelne dźwięki.","Sąsiednia struna nie odzywa się przypadkowo."],"mistake":"Samo uniesienie palca może zgasić dźwięk; użyj małego kontrolowanego ruchu.","source":"ch-06-4-source","prerequisites":["ch-06-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-06-6","chapter":6,"order":6,"title":"Bas naprzemienny","category":"Rytm","theory":"W fingerstyle bas naprzemienny tworzy stałe oparcie. Dla C możesz przeplatać C na strunie 5 i E na 4.","steps":["Ułóż C i graj basy 5–4–5–4 jako ćwierćnuty.","Dodaj palec m na strunie 2 pomiędzy pulsami 1 i 2 oraz 3 i 4.","Powtarzaj powoli przy 50 BPM."],"example":"1 i 2 i 3 i 4 i: p5 m2 p4 – p5 m2 p4 –","criteria":["Zagraj osiem taktów z nieprzerwanym basem.","Dodatkowe dźwięki mieszczą się między kliknięciami."],"mistake":"Nie przesuwaj basu w czasie, żeby zrobić miejsce palcom.","source":"intermediate","prerequisites":["ch-06-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-06-7","chapter":6,"order":7,"title":"Rozpisz prostą aranżację","category":"Repertuar","theory":"Aranżację budujemy warstwami: najpierw melodia, potem bas, na końcu wypełnienie. Wybierz prosty własny motyw.","steps":["Zagraj melodię E–G–E–D na pierwszej i drugiej strunie.","Dodaj bas E na początku pierwszego taktu i A na początku drugiego.","Dopiero gdy obie warstwy są pewne, dodaj jeden dźwięk akordu w pauzie."],"example":"Takt 1: bas E + E G E –; takt 2: bas A + C D C –","criteria":["Zagraj dwie warstwy przez cztery takty.","Zapisz melodię i miejsca basu w notatce."],"mistake":"Nie dodawaj pełnego akordu na każdy dźwięk melodii.","source":"classical","prerequisites":["ch-06-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-06-1","chapter":6,"order":8,"title":"Sześć wzorów arpeggia","category":"Technika","theory":"Ten sam akord można rozłożyć na wiele porządków. Zmiana wzoru ma być świadoma, a nie efektem gubienia palców.","steps":["Na Am zagraj p–i–m–a oraz p–a–m–i po cztery cykle.","Dodaj p–i–a–m i p–m–i–a, utrzymując równe ćwierćnuty.","Dodaj sześciodźwiękowe p–i–m–a–m–i oraz p–a–m–i–m–a."],"example":"p na 5, i na 3, m na 2, a na 1; 4 lub 6 dźwięków w cyklu.","criteria":["Zagraj każdy wzór cztery razy przy 50 BPM.","Nazwij wzór przed rozpoczęciem."],"mistake":"Nie wciskaj sześciu ćwierćnut w takt 4/4. Dla sześciu dźwięków licz 6/8.","source":"technique","prerequisites":["ch-06-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-06-2","chapter":6,"order":9,"title":"Małe barré przed arpeggiem","category":"Technika","theory":"Przy F xx3211 jeden palec obejmuje tylko struny 1 i 2. To przygotowanie do repertuaru, bez konieczności pełnego barré.","steps":["Ustaw sam palec wskazujący na 1/1 i 2/1, sprawdź każdą strunę.","Dodaj 3/2 oraz 4/3 i zagraj F od struny 4.","Zmieniaj Am–F po dwa takty, po każdej serii rozluźniając dłoń."],"example":"F: x x 3 2 1 1; nie graj strun 6 i 5.","criteria":["Zagraj cztery czyste arpeggia F.","Połącz Am–F przez osiem taktów w wolnym tempie."],"mistake":"Nie obejmuj wszystkich strun, jeśli zadanie wymaga tylko dwóch.","source":"technique","prerequisites":["deep-06-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-06-3","chapter":6,"order":10,"title":"Przygotowanie palców prawej dłoni","category":"Technika","theory":"Planting oznacza przygotowanie palca na strunie przed szarpnięciem. Pomaga w kontroli, ale może przerwać wybrzmiewanie, jeśli zastosujesz je zbyt wcześnie.","steps":["Na pustych strunach przygotuj i–m–a na 3–2–1 i zagraj kolejno.","Powtórz, przygotowując każdy palec tuż przed jego dźwiękiem.","Porównaj obie wersje na Am i wybierz tę, która zachowuje zamierzone legato."],"example":"Przygotuj → szarpnij → słuchaj długości poprzedniej nuty.","criteria":["Zagraj cztery cykle bez szukania strun.","Umiesz pokazać, kiedy przygotowanie tłumi potrzebny dźwięk."],"mistake":"Nie zamieniaj planting w obowiązek kładzenia wszystkich palców po każdym dźwięku.","source":"technique","prerequisites":["deep-06-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-06-4","chapter":6,"order":11,"title":"Bas podtrzymany przez cały takt","category":"Technika","theory":"Głosy mają własne długości. Bas może trwać cztery pulsy, chociaż melodia zmienia się na każdym z nich.","steps":["Zagraj E na pustej strunie 6 wraz z E na 1/0.","Dodaj melodię F–G–E na pulsach 2–3–4, nie dotykając basu.","W następnym takcie zmień bas na A, a melodię na C–D–C–B."],"example":"Bas E cały takt / góra E F G E; bas A / góra C D C B.","criteria":["Zagraj osiem taktów z pełną długością basu.","Tłumisz poprzedni bas przy wejściu nowego, jeśli współbrzmienie przeszkadza."],"mistake":"Nie myl długiego basu z głośnym basem.","source":"bach","prerequisites":["deep-06-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-06-5","chapter":6,"order":12,"title":"Legato w środku arpeggia","category":"Technika","theory":"Hammer-on i pull-off mogą działać nad wybrzmiewającym basem. Kluczowa jest równa głośność i brak dodatkowego ruchu kciuka.","steps":["Zagraj bas A na 5/0 i C na 2/1.","Dodaj hammer-on do D na 2/3, zachowując bas.","W kolejnym takcie zagraj D, pull-off do C i zakończ E na 1/0."],"example":"Bas: A — — —; góra: C D — E.","criteria":["Połącz cztery pary taktów przy 50 BPM.","Ozdobnik nie jest głośniejszy od głównej melodii."],"mistake":"Pull-off jest kontrolowanym ruchem, nie pionowym oderwaniem palca.","source":"technique","prerequisites":["deep-06-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-06-6","chapter":6,"order":13,"title":"Melodia, bas i środkowy głos","category":"Technika","theory":"W fakturze trzygłosowej nie wszystkie nuty są jednakowo ważne. Górna linia zwykle prowadzi, bas wspiera, a wypełnienie pozostaje w tle.","steps":["Na Em zagraj p na 6, i na 3, m na 2 i a na 1.","Zagraj osiem cykli, wyróżniając wyłącznie a.","Następnie świadomie wyróżnij bas, porównaj i wróć do prowadzenia melodii."],"example":"Melodia: wyraźna · bas: obecny · środek: cichy.","criteria":["Słyszysz różnicę między trzema poziomami głośności.","Zachowujesz ten balans także na Am."],"mistake":"Nie próbuj osiągnąć kontrastu samym przyspieszeniem melodii.","source":"roman","prerequisites":["deep-06-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"ch-06-8","chapter":6,"order":14,"title":"Wyzwanie: mała aranżacja fingerstyle","category":"Repertuar","theory":"W krótkim wykonaniu liczą się równy rytm, czytelna melodia i kontrolowany bas. Możesz rozwinąć własny motyw z poprzedniej lekcji.","steps":["Ułóż ośmiotaktową aranżację z melodii i basu.","Przećwicz po dwa takty, a następnie połącz całość przy 50–60 BPM.","Zagraj dwukrotnie, wyróżniając melodię dynamiką."],"example":"Forma: A (4 takty) + A′ (4 takty ze zmienionym zakończeniem)","criteria":["Zagraj osiem taktów bez zatrzymania.","Melodia pozostaje wyraźniejsza od basu i wypełnienia."],"mistake":"Nie przyspieszaj w łatwych fragmentach; dopasuj tempo do najtrudniejszego.","source":"classical","prerequisites":["deep-06-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-06","chapter":6,"order":15,"title":"Scena 6: Pierwszy repertuar palcami","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-06-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[10,25],"songChoices":["rep-house","rep-nothing","rep-hallelujah-picking"]},{"id":"side-06-1","chapter":6,"order":1,"title":"Pierwsze kroki Travis picking","category":"Technika","theory":"Stały bas naprzemienny można uzupełnić dźwiękami na słabych częściach pulsu. To uproszczony wzór przygotowujący do stylu.","steps":["Na C graj basy 5 i 4 naprzemiennie na każdy puls.","Dodaj strunę 2 po pierwszym i trzecim pulsie.","Ćwicz przy 45 BPM po dwa takty."],"example":"p5 m2 p4 – p5 m2 p4 –","criteria":["Wykonaj osiem taktów bez zakłócenia basu."],"mistake":"Nie zaczynaj od pełnego szybkiego wzoru.","source":"intermediate","prerequisites":["ch-06-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-06-2","chapter":6,"order":2,"title":"Naturalne flażolety","category":"Technika","theory":"Lekkie dotknięcie struny nad XII progiem pozwala wydobyć flażolet oktawowy. Nie dociskaj struny do gryfu.","steps":["Dotknij struny 1 dokładnie nad XII progiem.","Szarp strunę prawą dłonią i odsuń dotykający palec.","Powtórz na strunach 2 i 3."],"example":"XII próg: delikatny dotyk → szarpnięcie → odsunięcie","criteria":["Wydobądź trzy wyraźne flażolety na różnych strunach."],"mistake":"Zbyt silny nacisk zamieni flażolet w zwykły dźwięk.","source":"technique","prerequisites":["ch-06-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"branch-06-1","chapter":6,"order":3,"title":"Travis: cztery niezależne basy","category":"Technika","theory":"Kciuk może grać wszystkie ćwierćnuty, a palce wypełniać przestrzenie. Najpierw stabilny bas, dopiero później gęstość.","steps":["Na C graj 5–4–5–4 kciukiem przy 45 BPM.","Dodaj strunę 2 po 1 i strunę 1 po 3.","Powtórz na Am, potem zmieniaj chwyt co dwa takty."],"example":"1:p5 i:m2 2:p4 3:p5 i:a1 4:p4.","criteria":["Zagraj osiem taktów bez zaburzenia kciuka."],"mistake":"Nie przyspieszaj basu przy dodawaniu palców pomiędzy pulsami.","source":"technique","prerequisites":["ch-06-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Fingerstyle"},{"id":"branch-06-2","chapter":6,"order":4,"title":"Flażolety XII, VII i V","category":"Technika","theory":"Węzły drgającej struny dają różne składowe harmoniczne. Dotykasz nad progiem, nie dociskasz do podstrunnicy.","steps":["Wydobądź flażolet nad XII progiem struny 1.","Porównaj VII i V, szarpiąc bliżej mostka.","Wpleć trzy flażolety jako zakończenie krótkiego arpeggia."],"example":"XII: oktawa · VII: oktawa i kwinta · V: dwie oktawy.","criteria":["Uzyskaj czyste dźwięki w trzech miejscach."],"mistake":"Przy V progu potrzebna jest precyzja dotyku, nie większy nacisk.","source":"technique","prerequisites":["ch-06-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Klasyka"},{"id":"branch-06-3","chapter":6,"order":5,"title":"Tremolo: pierwszy równy cykl","category":"Technika","theory":"Tremolo p–a–m–i jest osobną koordynacją. Wolny, równy cykl przygotowuje ją lepiej niż szybka nierówna seria.","steps":["Zagraj p na 5, a–m–i na 1, po jednym dźwięku na klik 50 BPM.","Po ośmiu cyklach graj po dwa dźwięki na klik.","Porównaj głośność a, m oraz i i wróć do wolniejszej wersji, jeśli się rozjeżdża."],"example":"p a m i | p a m i; trzy palce na tej samej strunie.","criteria":["Zagraj 16 równych cykli bez narastającego napięcia."],"mistake":"Nie uznawaj tego wstępu za gotowość do Recuerdos de la Alhambra.","source":"technique","prerequisites":["ch-06-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Klasyka"},{"id":"ch-07-1","chapter":7,"order":1,"title":"Małe barré","category":"Technika","theory":"Barré pozwala jednym palcem docisnąć kilka strun. Zacznij od dwóch, zanim przejdziesz do pełnego chwytu.","steps":["Palcem 1 dociśnij struny 1 i 2 na pierwszym progu.","Zagraj je osobno, dobierając minimalny nacisk.","Dodaj palec 2 na strunie 3 próg 2: otrzymasz fragment F."],"example":"F: xxx211 (struny 3–2–1)","criteria":["Uzyskaj trzy czyste dźwięki w pięciu krótkich próbach.","Po każdej próbie rozluźnij dłoń; przy bólu przerwij."],"mistake":"Nie utrzymuj mocnego nacisku przez całą sesję.","source":"ch-07-1-source","prerequisites":["rep-06"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-07-2","chapter":7,"order":2,"title":"Pełne barré i ruchomy chwyt","category":"Technika","theory":"Chwyt F 133211 jest przesuniętym kształtem E. Dźwięk na szóstej strunie określa nazwę. Pełne barré może wymagać wielu krótkich sesji.","steps":["Przygotuj F i sprawdź struny pojedynczo.","Jeśli jest zbyt trudno, ćwicz ten sam kształt od V progu jako A.","Przesuń cały kształt o dwa progi i nazwij nowy akord."],"example":"F 133211 → G 355433 → A 577655","criteria":["Zagraj dwa wybrane ruchome akordy czysto w trzech próbach.","Wskaż dźwięk podstawowy każdego chwytu."],"mistake":"Nie dociskaj strun, które są już skrócone innymi palcami, większą siłą niż trzeba.","source":"ch-07-1-source","prerequisites":["ch-07-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-07-3","chapter":7,"order":3,"title":"Triady na trzech strunach","category":"Teoria","theory":"Małe chwyty pozwalają widzieć składniki harmonii i zostawiają miejsce melodii. Triada C to zawsze C–E–G, niezależnie od ułożenia.","steps":["Zagraj C na strunach 3–2–1 jako 5–5–3.","Nazwij dźwięki C–E–G.","Porównaj z układem 0–1–0, czyli G–C–E."],"example":"C: xxx553 = C E G; xxx010 = G C E","criteria":["Zagraj oba układy i nazwij wszystkie dźwięki.","Wyjaśnij, dlaczego oba są akordem C."],"mistake":"Nie utożsamiaj nazwy akordu z najwyższym dźwiękiem chwytu.","source":"theory","prerequisites":["ch-07-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-07-4","chapter":7,"order":4,"title":"Przewroty i najbliższa droga","category":"Teoria","theory":"Przewrót zmienia najniższy dźwięk akordu. Wybór bliskich układów ogranicza skoki głosów i nadaje akompaniamentowi płynność.","steps":["Zagraj C jako xxx010.","Zagraj F jako xxx211, a G jako xxx433.","Wróć do C i posłuchaj ruchu najwyższych głosów."],"example":"C: G C E → F: A C F → G: B D G","criteria":["Połącz trzy triady w równych ćwierćnutach.","Wskaż jeden wspólny dźwięk C i F."],"mistake":"Nie przenoś całej ręki dalej niż wymaga następny układ.","source":"theory","prerequisites":["ch-07-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-07-5","chapter":7,"order":5,"title":"Kolor akordów septymowych","category":"Teoria","theory":"Do triady dodajemy septymę. Cmaj7 zawiera B, C7 ma B♭, a Am7 ma G. To różne funkcje i brzmienia.","steps":["Zagraj Cmaj7 x32000 i porównaj z C x32010.","Zagraj Am7 x02010 i E7 020100.","Nazwij dodatkowy dźwięk każdego akordu."],"example":"Cmaj7: C E G B · Am7: A C E G · E7: E G♯ B D","criteria":["Zagraj trzy chwyty czysto.","Rozróżnij w opisie maj7, 7 i m7."],"mistake":"Nie traktuj zapisu C7 jako skrótu Cmaj7.","source":"theory","prerequisites":["ch-07-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-07-6","chapter":7,"order":6,"title":"Przenieś progresję","category":"Teoria","theory":"Transpozycja zachowuje relacje między akordami. I–V–vi–IV w C to C–G–Am–F, a w G: G–D–Em–C.","steps":["Zapisz stopnie progresji C–G–Am–F.","Przenieś każdy stopień do G-dur.","Zagraj obie wersje wolno; F możesz zagrać jako małą triadę."],"example":"C: I V vi IV → C G Am F; G: G D Em C","criteria":["Zagraj progresję w dwóch tonacjach.","Wyjaśnij, dlaczego akord vi pozostaje molowy."],"mistake":"Nie przesuwaj jedynie pierwszego akordu, pozostawiając resztę bez zmian.","source":"theory","prerequisites":["ch-07-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-07-7","chapter":7,"order":7,"title":"Tonika, subdominanta, dominanta","category":"Słuch","theory":"W prostej harmonii tonalnej I daje oparcie, IV rozwija, a V prowadzi z powrotem do I. To użyteczny model słuchowy, nie reguła każdej muzyki.","steps":["Zagraj C–F–G7–C; G7 to 320001.","Zatrzymaj się raz na G7 i posłuchaj oczekiwania.","Dokończ na C i zaśpiewaj B–C nad zmianą G7–C."],"example":"I–IV–V7–I = C–F–G7–C","criteria":["Usłysz różnicę między zatrzymaniem na V a I.","Pokaż ruch B–C w kadencji."],"mistake":"Nie sprowadzaj wszystkich piosenek do jednego schematu funkcji.","source":"ear","prerequisites":["ch-07-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-07-1","chapter":7,"order":8,"title":"Sus2 i sus4 w otwartej pozycji","category":"Teoria","theory":"W sus tercję zastępuje sekunda albo kwarta. Taki akord nie ma tercji określającej dur lub moll; nie zawsze musi natychmiast się rozwiązać.","steps":["Zagraj D xx0232, Dsus2 xx0230 i Dsus4 xx0233.","Nazwij górne dźwięki F♯, E i G.","Ułóż cztery takty D–Dsus4–D–Dsus2, zmieniając tylko potrzebny palec."],"example":"D: D F♯ A · Dsus2: D E A · Dsus4: D G A.","criteria":["Zagraj cztery cykle bez zatrzymania.","Wyjaśnij, dlaczego sus4 nie oznacza dodania czwartego dźwięku do pełnej triady."],"mistake":"Nie myl sus2 z add9, który zachowuje tercję.","source":"chordmap","prerequisites":["ch-07-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-07-2","chapter":7,"order":9,"title":"Pryma nie zawsze jest basem","category":"Teoria","theory":"Nazwa akordu wynika z jego budowy, a nie zawsze z najniższego dźwięku. C/E nadal zawiera C–E–G, lecz E jest w basie.","steps":["Zagraj C x32010 i C/E 032010.","Wypisz składniki obu chwytów od najniższej struny.","Porównaj G 320003 i G/B x20003 w przejściu C–G/B–Am."],"example":"C/E: pryma C, bas E. G/B: pryma G, bas B.","criteria":["Zagraj progresję z opadającym basem C–B–A.","Nazwij niezależnie prymę i bas każdego chwytu."],"mistake":"Nie stosuj zasady „najniższa nuta daje nazwę akordu” do przewrotów.","source":"inversions","prerequisites":["deep-07-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-07-3","chapter":7,"order":10,"title":"Triady na strunach 1–2–3","category":"Teoria","theory":"Małe triady pozwalają zobaczyć składniki akordu i prowadzić głosy krótkimi ruchami. Trzy struny wystarczą do pełnej triady.","steps":["Zagraj C: struny 3/5, 2/5, 1/3.","Zagraj F: 3/5, 2/6, 1/5 oraz G: 3/4, 2/3, 1/3.","Nazwij każdy dźwięk, potem graj C–F–G–C po dwa pulsy na chwyt."],"example":"C: C E G · F: C F A · G: B D G.","criteria":["Zagraj cztery obiegi przy 50 BPM.","Wskaż prymę, tercję i kwintę w każdym układzie."],"mistake":"Układ palców to skutek budowy akordu, nie zamiennik jej znajomości.","source":"triads","prerequisites":["deep-07-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-07-4","chapter":7,"order":11,"title":"Trzy rodzaje septymy w praktyce","category":"Teoria","theory":"Cmaj7, C7 i Cm7 różnią się tercją oraz septymą. Sam symbol 7 oznacza akord dominantowy, nie dowolny akord z czterech nut.","steps":["Zapisz Cmaj7 C–E–G–B, C7 C–E–G–B♭ i Cm7 C–E♭–G–B♭.","Zagraj składniki kolejno w wygodnych miejscach gryfu.","Porównaj proste chwyty Cmaj7 x32000, C7 x32310 oraz Am7 x02010 jako inny przykład m7."],"example":"maj7: 1 3 5 7 · 7: 1 3 5 ♭7 · m7: 1 ♭3 5 ♭7.","criteria":["Zbuduj trzy jakości od C na kartce i jako arpeggio.","Rozpoznaj różnicę Cmaj7 i C7 po usłyszeniu obu."],"mistake":"Nie oceniaj jakości akordu wyłącznie jako „wesoły” albo „smutny”.","source":"sevenths","prerequisites":["deep-07-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-07-5","chapter":7,"order":12,"title":"Akord z ruchomego kształtu","category":"Technika","theory":"Przesunięty kształt E lub A zmienia akord, ponieważ przesuwa się jego pryma. Puste struny trzeba wtedy zastąpić barré lub pominąć.","steps":["Zagraj F 133211 i G 355433, odnajdując prymy na strunie 6.","Porównaj Bm x24432 i Cm x35543 z prymą na 5.","Ćwicz po dwa chwyty, z pełnym rozluźnieniem między seriami."],"example":"Kształt Em + barré na V = Am; pryma na 6/5.","criteria":["Nazwij cztery przesunięte chwyty bez liczenia od początku gryfu.","Zagraj je czysto w krótkiej serii, bez bólu."],"mistake":"Nie utrzymuj barré podczas przerwy ani nie naciskaj maksymalną siłą.","source":"chordmap","prerequisites":["deep-07-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"deep-07-6","chapter":7,"order":13,"title":"Transpozycja akompaniamentu bez kapodastra","category":"Teoria","theory":"Transpozycja zachowuje relacje stopni, ale zmienia wysokość toniki. Umiejętność przydaje się do dopasowania akompaniamentu do głosu.","steps":["Zapisz C–Am–F–G jako I–vi–IV–V.","Przenieś do G: G–Em–C–D.","Zagraj obie wersje z tym samym rytmem, a potem zanuć melodię o stopniach 3–2–1."],"example":"C-dur → G-dur; duże cyfry dur, małe moll.","criteria":["Zagraj cztery obiegi w obu tonacjach.","Wyjaśnij, dlaczego Am zmienia się na Em, a nie E."],"mistake":"Nie przesuwaj każdej nazwy o przypadkową liczbę liter bez sprawdzenia jakości.","source":"major","prerequisites":["deep-07-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[3,6]},{"id":"ch-07-8","chapter":7,"order":14,"title":"Wyzwanie: dwie tonacje","category":"Repertuar","theory":"Sprawdź, czy rozumiesz progresję niezależnie od zapamiętanych chwytów. Wybierz poznany akompaniament i przenieś go.","steps":["Zagraj I–V–vi–IV w C-dur przez osiem taktów.","Zagraj ten sam rytm w G-dur przez osiem taktów.","W jednej wersji wykorzystaj przynajmniej jedną małą triadę zamiast pełnego chwytu."],"example":"C G Am F → G D Em C","criteria":["Obie wersje zachowują rytm przy 60 BPM.","Nazwij stopnie oraz dźwięk podstawowy każdego akordu."],"mistake":"Nie zwiększaj tempa po zmianie na łatwiejszą tonację.","source":"intermediate","prerequisites":["deep-07-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-07","chapter":7,"order":15,"title":"Scena 7: Cała forma, swobodne chwyty","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-07-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[10,25],"songChoices":["rep-let","rep-hallelujah-full","rep-wish-full"]},{"id":"side-07-1","chapter":7,"order":1,"title":"Jazzowe ii–V–I","category":"Teoria","theory":"Progresja ii–V–I jest podstawowym ruchem harmonicznym w wielu standardach. W C-dur to Dm7–G7–Cmaj7.","steps":["Zagraj Dm7 xx0211, G7 320001 i Cmaj7 x32000.","Nazwij tercję i septymę każdego akordu.","Zagraj po jednym takcie Dm7 i G7 oraz dwa Cmaj7."],"example":"| Dm7 | G7 | Cmaj7 | Cmaj7 |","criteria":["Zagraj cztery obiegi i wskaż rozwiązanie B–C."],"mistake":"Nie pomijaj jakości septymy w nazwach.","source":"theory","prerequisites":["ch-07-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-07-2","chapter":7,"order":2,"title":"Bossa: niezależny bas i akord","category":"Rytm","theory":"To uproszczone ćwiczenie synkopy inspirowane bossa novą, nie pełny wzór stylistyczny.","steps":["Na Am7 graj bas na 1 i 3.","Dodaj lekkie górne dźwięki na 2 oraz „i” po 3.","Połącz z Dm7, po dwa takty na akord przy 50 BPM."],"example":"1: bas · 2: akord · 3: bas · 3-i: akord","criteria":["Utrzymaj osiem taktów z cichym basem i równą synkopą."],"mistake":"Nie akcentuj wszystkich dźwięków jednakowo.","source":"intermediate","prerequisites":["ch-07-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"branch-07-1","chapter":7,"order":3,"title":"Szkielety akordów: tercja i septyma","category":"Teoria","theory":"Shell voicing pomija część dźwięków, zachowując informację o jakości. Pryma może być zagrana osobno jako bas.","steps":["Zapisz tercję i septymę Dm7: F–C, G7: B–F, Cmaj7: E–B.","Znajdź każdą parę na dwóch sąsiednich strunach.","Zagraj bas, potem parę, po jednym takcie na akord."],"example":"Dm7 → G7 → Cmaj7: słuchaj ruchu C→B i F→E.","criteria":["Wykonaj cztery kadencje i nazwij wszystkie pary."],"mistake":"Nie pomijaj tercji i septymy tylko po to, aby zachować znany chwyt.","source":"sevenths","prerequisites":["ch-07-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Jazz i bossa"},{"id":"branch-07-2","chapter":7,"order":4,"title":"Blues dwudźwiękami","category":"Technika","theory":"Dwudźwięk prymy i kwinty daje otwarte brzmienie bez tercji. Jest przydatny także na gitarze klasycznej, bez przesteru.","steps":["Zagraj E na 6/0 i B na 5/2 jednocześnie.","Zostaw E i przesuń B na C♯ na 5/4.","Przeplataj obie pary ćwierćnutami, potem w shuffle."],"example":"E–B → E–C♯; kwinta przechodzi w sekstę.","criteria":["Zagraj osiem taktów bez przypadkowego uderzania innych strun."],"mistake":"Nie rozciągaj palców na siłę; przerwij, jeśli ruch jest niewygodny.","source":"intermediate","prerequisites":["ch-07-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Blues"},{"id":"branch-07-3","chapter":7,"order":5,"title":"Dim7 i półzmniejszony","category":"Teoria","theory":"Akord zmniejszony septymowy i półzmniejszony różnią się septymą. Ich podobne symbole łatwo pomylić.","steps":["Zapisz Bm7♭5: B–D–F–A.","Porównaj Bdim7: B–D–F–A♭.","Zagraj oba jako arpeggia, następnie rozwiąż Bm7♭5–E7–Am."],"example":"m7♭5: 1 ♭3 ♭5 ♭7; dim7: 1 ♭3 ♭5 ♭♭7.","criteria":["Nazwij różnicę i zagraj oba zbiory od B."],"mistake":"A♭ w Bdim7 jest zapisem septymy zmniejszonej, nie zwykłej seksty w nazwie akordu.","source":"chordmap","prerequisites":["ch-07-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[3,6],"branch":"Jazz i bossa"},{"id":"ch-08-1","chapter":8,"order":1,"title":"Dur i moll naturalny","category":"Teoria","theory":"A-moll naturalny zawiera te same dźwięki co C-dur, ale inną tonikę. Względem A stopnie to 1–2–♭3–4–5–♭6–♭7.","steps":["Zagraj A–B–C–D–E–F–G–A w wygodnej pozycji.","Porównaj zakończenia tej samej frazy na C i na A.","Zagraj Am przed frazą, aby ustalić molowy punkt odniesienia."],"example":"A B C D E F G A · C D E F G A B C","criteria":["Zagraj obie skale i wskaż ich toniki.","Stwórz dwie frazy z tymi samymi dźwiękami, ale innym centrum."],"mistake":"Te same dźwięki nie oznaczają tego samego centrum tonalnego.","source":"theory","prerequisites":["rep-07"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-08-2","chapter":8,"order":2,"title":"Połącz pozycje","category":"Technika","theory":"Gra wzdłuż gryfu pozwala unikać zamknięcia w jednym kształcie. Pozycję zmieniaj na zaplanowanym dźwięku, nie przypadkowym skoku.","steps":["Zagraj A–C–D–E–G na strunie 1: 5–8–10–12–15; na klasycznej ogranicz się do wygodnego zakresu.","Alternatywnie zagraj na strunie 3: 2–5–7–9–12.","Połącz pozycję otwartą z V progiem przez wspólny dźwięk C."],"example":"Na strunie 3: A(2) C(5) D(7) E(9) G(12)","criteria":["Zagraj frazę przechodzącą między dwiema pozycjami.","Przesunięcie jest rytmiczne i bez niezamierzonej przerwy."],"mistake":"Nie forsuj wysokich progów niedostępnych wygodnie na Twojej gitarze.","source":"intermediate","prerequisites":["ch-08-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-08-3","chapter":8,"order":3,"title":"Arpeggia za zmianą akordu","category":"Teoria","theory":"Arpeggio w improwizacji pokazuje dźwięki aktualnego akordu. Na Am–Dm–E7 zmieniają się cele melodii, zwłaszcza G♯ w E7.","steps":["Zagraj osobno A–C–E, D–F–A oraz E–G♯–B–D.","Połącz po jednym takcie każdego arpeggia przy 50 BPM.","Zakończ G♯–A przy powrocie z E7 do Am."],"example":"Am: A C E · Dm: D F A · E7: E G♯ B D","criteria":["Zagraj składniki trzech akordów bez pomylenia G i G♯.","Wyląduj na A przy powrocie do Am."],"mistake":"Nie pozostawaj automatycznie w A-moll naturalnym nad każdym E7.","source":"theory","prerequisites":["ch-08-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-08-4","chapter":8,"order":4,"title":"Blues w dwunastu taktach","category":"Repertuar","theory":"Podstawowa forma bluesa łączy I7, IV7 i V7 w dwunastu taktach. Najpierw naucz się słyszeć formę, potem dodawaj ozdobniki.","steps":["Zagraj E7–A7–B7 zgodnie z przykładem; A7 x02020, B7 x21202.","Licz każdy takt na głos przy 60 BPM.","Przez drugie okrążenie zagraj krótką odpowiedź pentatoniczną w pauzach."],"example":"| E7 | E7 | E7 | E7 | A7 | A7 | E7 | E7 | B7 | A7 | E7 | B7 |","criteria":["Zagraj dwa okrążenia bez zgubienia formy.","Wskaż takty przejścia na IV i V."],"mistake":"Nie myl dwunastu taktów z dwunastoma uderzeniami.","source":"beginner","prerequisites":["ch-08-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-08-5","chapter":8,"order":5,"title":"Celuj w tercję","category":"Improwizacja","theory":"Tercja jasno pokazuje jakość akordu. Bliskie przejście między składnikami kolejnych akordów spaja melodię z harmonią.","steps":["Nad C zagraj E, nad Am C, nad F A, nad G B.","Dodaj przed każdym celem jeden dźwięk sąsiedni ze skali C.","Powtórz progresję cztery razy, zmieniając rytm dojścia."],"example":"C→E · Am→C · F→A · G→B","criteria":["Traf w tercję na pierwszym pulsie każdego akordu.","Zagraj dwie różne rytmicznie wersje tej samej linii."],"mistake":"Nie trafiaj w cel dopiero po zakończeniu właściwego akordu.","source":"intermediate","prerequisites":["ch-08-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-08-6","chapter":8,"order":6,"title":"Transkrypcja dwóch taktów","category":"Słuch","theory":"Transkrypcja zaczyna się od słuchania i śpiewania krótkiej frazy. Zapis może początkowo być nazwami dźwięków i rytmem, nie pełnymi nutami.","steps":["Wybierz dwa takty prostej melodii z legalnie dostępnego nagrania.","Odsłuchaj wielokrotnie i wyklaszcz rytm.","Zaśpiewaj, znajdź dźwięki, zapisz i porównaj z nagraniem."],"example":"Kolejność: rytm → pierwszy dźwięk → kierunek → pozostałe dźwięki","criteria":["Odtwórz dwa takty zgodnie z nagraniem.","Zapisz rytm i wysokości bez korzystania z gotowej tabulatury."],"mistake":"Nie wybieraj na start szybkiej solówki pełnej ozdobników.","source":"ear","prerequisites":["ch-08-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-08-7","chapter":8,"order":7,"title":"Buduj napięcie i rozwiązanie","category":"Improwizacja","theory":"Dźwięk spoza akordu może prowadzić do stabilnego składnika. Odbiór zależy od rytmu i harmonii, więc zawsze sprawdzaj go w kontekście.","steps":["Nad C zagraj D–E, F–E oraz B–C.","Najpierw zatrzymaj pierwszy dźwięk na dwa pulsy, potem rozwiąż.","Wpleć dwie pary w czterotaktową frazę."],"example":"Nad C: 2→3, 4→3, 7→1","criteria":["Zagraj dwie frazy ze słyszalnym rozwiązaniem.","Nazwij dźwięk docelowy i akord, do którego należy."],"mistake":"Nie używaj napięcia bez sprawdzenia, jak brzmi nad aktualnym akordem.","source":"theory","prerequisites":["ch-08-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-08-1","chapter":8,"order":8,"title":"Moll naturalne, harmoniczne i melodyczne","category":"Teoria","theory":"W a-moll naturalnym jest G, w harmonicznym G♯. W klasycznym ćwiczeniu melodycznego podnosi się F i G w górę, a wraca naturalnym w dół. To materiał, nie nakaz dla każdej melodii.","steps":["Zagraj A–B–C–D–E–F–G–A.","Zmień G na G♯ i posłuchaj prowadzenia do A.","Porównaj F♯–G♯–A z F–G–A i użyj obu jako zakończeń krótkiej frazy."],"example":"Naturalna: 1 2 ♭3 4 5 ♭6 ♭7; harmoniczna: podniesiony VII.","criteria":["Zagraj trzy warianty i nazwij zmienione dźwięki.","Wybierz G♯ nad E7 prowadzącym do Am."],"mistake":"Jazzowe użycie moll melodycznej może zachowywać podniesione stopnie w obu kierunkach.","source":"minor","prerequisites":["ch-08-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-08-2","chapter":8,"order":9,"title":"Połącz dwie pozycje pentatoniki","category":"Technika","theory":"Łączenie pozycji ma pozwolić kontynuować frazę, a nie uruchamiać kolejny mechaniczny schemat. Wspólny dźwięk jest punktem przejścia.","steps":["Zagraj A–C–D–E na strunie 3: 2–5–7–9.","Znajdź te same dźwięki w niższej pozycji na strunach 5–4.","Ułóż frazę, która przechodzi przez wspólne E, i wróć inną drogą."],"example":"A C D E G; przejście może wypaść na długim E.","criteria":["Zagraj tę samą frazę w dwóch pozycjach.","Wykonaj trzy płynne przejścia bez dodatkowej nuty."],"mistake":"Nie przesuwaj ręki przypadkowo podczas szybkiego przebiegu.","source":"technique","prerequisites":["deep-08-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-08-3","chapter":8,"order":10,"title":"Arpeggia przez zmianę akordu","category":"Improwizacja","theory":"Arpeggio solowe ukazuje harmonię pojedynczymi dźwiękami. Najbliższy składnik następnego akordu często daje płynniejszy ruch niż powrót do prymy.","steps":["Zagraj A–C–E–G dla Am7, następnie D–F–A–C dla Dm7.","Połącz E z F oraz G z A przez granicę taktów.","Ułóż osiem taktów, rozpoczynając kolejne akordy od tercji."],"example":"Am7: A C E G → Dm7: D F A C; E→F to półton.","criteria":["Zagraj cztery zmiany z różnymi najbliższymi celami.","Nazwij funkcję dźwięku na początku każdego akordu."],"mistake":"Nie traktuj arpeggia wyłącznie jako ćwiczenia od dołu do góry.","source":"sevenths","prerequisites":["deep-08-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-08-4","chapter":8,"order":11,"title":"Blues: tercja mała i wielka","category":"Słuch","theory":"W bluesie napięcie między tercją małą i wielką jest środkiem wyrazu. Na nylonie można je pokazać półtonowym ruchem bez szerokiego podciągania struny.","steps":["Nad A7 x02020 porównaj C na 2/1 i C♯ na 2/2.","Zagraj C–C♯–E, potem E–C–A.","Wstaw oba motywy w pierwsze cztery takty bluesa A."],"example":"A7 zawiera C♯; C jest ekspresyjnym napięciem, które możesz rozwiązać.","criteria":["Zagraj dwie frazy z celowym rozwiązaniem C→C♯.","Słyszysz różnicę napięcia i stabilnego zakończenia."],"mistake":"Nie wymuszaj rockowych bendów na klasycznej gitarze.","source":"intermediate","prerequisites":["deep-08-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-08-5","chapter":8,"order":12,"title":"Transkrypcja rytmu przed wysokością","category":"Słuch","theory":"Krótki fragment jest łatwiejszy do odtworzenia, gdy rozdzielisz rytm i wysokość. Zwolnione odtwarzanie pomaga, ale ostatecznie wróć do zwykłego tempa.","steps":["Wybierz 2–4 sekundy melodii z dostępnej lekcji repertuarowej.","Wyklaszcz rytm, potem znajdź pierwszy i ostatni dźwięk.","Uzupełnij środek, porównaj z filmem i zapisz poprawkę."],"example":"Najpierw puls i długości → skrajne dźwięki → reszta frazy.","criteria":["Odtwórz krótki fragment zgodnie z rytmem i wysokościami.","Przenieś go o ton wyżej, zachowując relacje."],"mistake":"Nie transkrybuj całego solo naraz; jeden dokładny fragment wystarczy.","source":"ear","prerequisites":["deep-08-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-08-6","chapter":8,"order":13,"title":"Solo ma formę i kulminację","category":"Improwizacja","theory":"Rozwój solo może wynikać z gęstości rytmu, rejestru i dynamiki. Kulminacja potrzebuje kontrastu z wcześniejszym spokojem.","steps":["Zaplanuj 16 taktów: 4 oszczędne, 4 z wariacją, 4 intensywniejsze, 4 zamykające.","Użyj jednego motywu i najwyższy dźwięk zostaw na trzecią część.","Zagraj plan nad znaną harmonią, potem opisz, czy kulminacja była słyszalna."],"example":"A → A′ → kontrast → powrót; nie rosnące tempo.","criteria":["Wykonaj 16 taktów z rozpoznawalnym łukiem.","Końcowa fraza reaguje na ostatni akord."],"mistake":"Więcej nut w każdej kolejnej sekundzie nie jest jedynym sposobem budowania napięcia.","source":"practice","prerequisites":["deep-08-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"ch-08-8","chapter":8,"order":14,"title":"Wyzwanie: solo słyszące harmonię","category":"Improwizacja","theory":"Solo ma pokazać zmiany C–Am–F–G, nawet gdy nie grasz pełnych akordów. Pomogą tercje, motyw i zakończenie na C.","steps":["Zagraj progresję, a potem cztery obiegi melodii po jednym takcie na akord.","Na początku każdego taktu traf w składnik aktualnego akordu.","W drugim obiegu powtórz motyw, w ostatnim rozwiąż B–C."],"example":"| C | Am | F | G | × 4, następnie C","criteria":["Zagraj 16 taktów przy 60 BPM z celami zgodnymi z akordami.","Zastosuj motyw, pauzy i świadome zakończenie."],"mistake":"Nie oceniaj zgodności wyłącznie po użyciu skali C-dur.","source":"intermediate","prerequisites":["deep-08-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-08","chapter":8,"order":15,"title":"Scena 8: Solo słyszy harmonię","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-08-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[15,40],"songChoices":["rep-autumn","rep-stand-target","rep-knock-solo"]},{"id":"side-08-1","chapter":8,"order":1,"title":"Shuffle bez pośpiechu","category":"Rytm","theory":"Shuffle opiera się na podziale triolowym: gramy pierwszy i trzeci składnik trioli. Nie jest to równa para ósemek.","steps":["Powiedz tri-o-la na każdy puls metronomu.","Klaszcz na tri oraz la, pozostawiając środek cichy.","Przenieś rytm na akord E7 przez osiem taktów."],"example":"1-(2)-3 · 1-(2)-3 w każdej trioli","criteria":["Zagraj osiem taktów i odróżnij je od prostych ósemek."],"mistake":"Nie zastępuj triolowego podziału przypadkowym opóźnianiem.","source":"beginner","prerequisites":["ch-08-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-08-2","chapter":8,"order":2,"title":"Przepisz i przekształć frazę","category":"Słuch","theory":"Transkrypcja staje się własnym językiem, gdy rozumiesz i przekształcasz materiał.","steps":["Odtwórz ze słuchu krótką frazę z wybranego nagrania.","Nazwij jej stopnie względem toniki.","Przenieś frazę do innej tonacji i zmień zakończenie."],"example":"Oryginał → stopnie → transpozycja → wariacja","criteria":["Zagraj frazę w dwóch tonacjach oraz własną wariację."],"mistake":"Nie ucz się wyłącznie ruchu palców bez relacji dźwięków.","source":"ear","prerequisites":["ch-08-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Słuch i czytanie"},{"id":"branch-08-1","chapter":8,"order":3,"title":"ii–V–i w moll","category":"Improwizacja","theory":"Kadencja molowa często wykorzystuje dominantę z podwyższonym VII stopniem tonacji. W a-moll E7 wnosi G♯.","steps":["Zagraj kolejno składniki Bm7♭5, E7 i Am.","Zbuduj linię A–G♯–A przez trzy akordy.","Dodaj po jednym dźwięku poprzedzającym każdy cel i wykonaj cztery obiegi."],"example":"Bm7♭5: B D F A → E7: E G♯ B D → Am: A C E.","criteria":["Zagraj cztery frazy z wyraźnym rozwiązaniem G♯→A."],"mistake":"Nie używaj G naturalnego jako przypadkowego celu nad E7.","source":"minor","prerequisites":["ch-08-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Jazz i bossa"},{"id":"branch-08-2","chapter":8,"order":4,"title":"Chorus i turnaround","category":"Improwizacja","theory":"W bluesie ostatnie takty prowadzą do początku kolejnego obiegu. Rozpoznawanie formy jest ważniejsze od liczby zagrywek.","steps":["Rozpisz 12 taktów bluesa w E z rozdziału 8.","Zagraj basy i licz głośno numery taktów.","Dodaj własną frazę w taktach 11–12, prowadzącą do E na początku następnego obiegu."],"example":"9:B7 · 10:A7 · 11:E7 · 12:B7 → 1:E7.","criteria":["Wykonaj dwa chorusy bez pomylenia miejsca powrotu."],"mistake":"Nie kończ automatycznie po ośmiu taktach, gdy forma ma dwanaście.","source":"intermediate","prerequisites":["ch-08-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Blues"},{"id":"branch-08-3","chapter":8,"order":5,"title":"Transkrypcja basu","category":"Słuch","theory":"Linia basowa ułatwia rozpoznanie harmonii, ale bas nie zawsze jest prymą. Najpierw odtwórz dźwięki, potem wnioskuj o akordach.","steps":["Wybierz cztery takty lekcji piosenki i słuchaj tylko basu.","Znajdź po jednej najniższej nucie na zmianę harmonii.","Porównaj z chwytami nauczyciela i zaznacz ewentualny przewrót."],"example":"Usłysz bas → znajdź nutę → sprawdź akord → nazwij przewrót.","criteria":["Odtwórz bas czterech taktów i wyjaśnij jego relację do akordów."],"mistake":"Nie zgaduj nazwy akordu wyłącznie na podstawie jednej najniższej nuty.","source":"inversions","prerequisites":["ch-08-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Słuch i czytanie"},{"id":"ch-09-1","chapter":9,"order":1,"title":"Prowadź głosy najkrótszą drogą","category":"Teoria","theory":"Voice leading śledzi ruch pojedynczych dźwięków akordów. Dźwięki wspólne można zatrzymać, a pozostałe przesunąć blisko.","steps":["Zagraj C xxx010 i Am xxx210.","Zatrzymaj C i E na strunach 2 i 1, zmień tylko G na A na strunie 3.","Dodaj F xxx211, zmieniając E na F."],"example":"G–C–E → A–C–E → A–C–F","criteria":["Połącz trzy układy płynnie.","Nazwij dwa głosy pozostające na miejscu przy pierwszej zmianie."],"mistake":"Nie odrywaj wszystkich palców, jeśli część może zostać.","source":"theory","prerequisites":["rep-08"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-09-2","chapter":9,"order":2,"title":"Synkopa z zachowanym basem","category":"Rytm","theory":"Synkopa przenosi akcent na słabszą część taktu. Bas i liczenie pomagają utrzymać orientację.","steps":["Licz 1-i-2-i-3-i-4-i przy 50 BPM.","Graj bas C na 1 i 3, akord na „i” po 2 i po 4.","Powtórz osiem taktów, a potem zmień C na Am."],"example":"BAS – – akord BAS – – akord (osiem ósemek)","criteria":["Zagraj osiem taktów bez przesunięcia basu.","Potrafisz wyklaskać same akcenty akordu."],"mistake":"Nie przesuwaj całego pulsu wraz z akcentem synkopowanym.","source":"beginner","prerequisites":["ch-09-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-09-3","chapter":9,"order":3,"title":"Kolory: add9 i maj7","category":"Teoria","theory":"Rozszerzenia dodają barwy. Add9 dodaje dziewiąty stopień bez wymaganej septymy; maj7 zawiera septymę wielką.","steps":["Zagraj C x32010, Cadd9 x32030 i Cmaj7 x32000.","Wskaż zmieniający się dźwięk na strunie 2.","Użyj tych barw w dwutaktowym akompaniamencie, pozostawiając bas C."],"example":"C → Cadd9 (D) → Cmaj7 (B)","criteria":["Usłysz i nazwij dodatkowy dźwięk każdego chwytu.","Zagraj krótką progresję bez przypadkowego tłumienia melodii."],"mistake":"Nie dodawaj rozszerzenia, jeśli koliduje z zamierzoną melodią.","source":"theory","prerequisites":["ch-09-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-09-4","chapter":9,"order":4,"title":"Tryb jako brzmienie","category":"Teoria","theory":"Modalność wynika z centrum i charakterystycznych dźwięków. D dorycki to D–E–F–G–A–B–C, z wielką sekstą B względem D.","steps":["Zagraj bas D i potwierdź Dm.","Zagraj frazę D–F–A–B–A–F–D.","Porównaj B z B♭ w tej samej frazie, utrzymując D jako centrum."],"example":"D dorycki: 1 2 ♭3 4 5 6 ♭7","criteria":["Zagraj dwie frazy z charakterystycznym B nad Dm.","Wyjaśnij różnicę między D doryckim a D-moll naturalnym."],"mistake":"Samo zagranie C-dur od D nie ustanawia jeszcze słyszalnego centrum D.","source":"theory","prerequisites":["ch-09-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-09-5","chapter":9,"order":5,"title":"Melodia decyduje o chwycie","category":"Repertuar","theory":"Przy aranżacji solo najwyższy dźwięk chwytu często powinien odpowiadać melodii. Najpierw znajdź melodię, potem dopasuj akord.","steps":["W C-dur wybierz melodię E–G–A–G.","Znajdź ją na strunie 1 progach 0–3–5–3.","Pod E zagraj C, pod G małą triadę C, a pod A Am; sprawdź wygodę."],"example":"Melodia: E G A G; propozycja harmonii: C C Am C","criteria":["Zagraj cztery takty z melodią na górze.","Każdy chwyt pozostawia melodię czytelną."],"mistake":"Nie zmieniaj melodii tylko dlatego, że znasz jeden chwyt akordu.","source":"classical","prerequisites":["ch-09-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-09-6","chapter":9,"order":6,"title":"Forma i kontrast","category":"Repertuar","theory":"Aranżacja potrzebuje oddechu i kontrastu. Forma A–A′–B–A pozwala rozwinąć pomysł bez ciągłego dodawania nowych tematów.","steps":["Ułóż czterotaktowe A i wariację A′.","Napisz kontrastowe B, zmieniając rytm lub rejestr.","Wróć do A i zaplanuj cichsze zakończenie."],"example":"A (4) → A′ (4) → B (4) → A (4)","criteria":["Zagraj 16 taktów z rozpoznawalnym powrotem tematu.","Zapisz jeden świadomy kontrast sekcji B."],"mistake":"Kontrast nie wymaga zmiany wszystkiego jednocześnie.","source":"intermediate","prerequisites":["ch-09-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-09-7","chapter":9,"order":7,"title":"Zagraj bez podpórek","category":"Słuch","theory":"Pamięć muzyczna obejmuje melodię, harmonię i formę. Ćwicz rozpoczynanie z różnych miejsc, aby nie polegać jedynie na pamięci ruchowej.","steps":["Wybierz osiem taktów własnej aranżacji.","Zaśpiewaj melodię bez gitary i nazwij akordy.","Zagraj od początku, od taktu 3 i od taktu 5."],"example":"Punkty startu: 1 → 5 → 3 → całość","criteria":["Rozpocznij poprawnie z trzech miejsc.","Po pomyłce wróć do następnego punktu formy."],"mistake":"Nie utrwalaj nawyku wracania wyłącznie do pierwszego taktu.","source":"ear","prerequisites":["ch-09-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-09-1","chapter":9,"order":8,"title":"Akordy add9, 9 i 13","category":"Teoria","theory":"Add9 dodaje nonę do triady bez obowiązkowej septymy. Symbol 9 zwykle zakłada septymę, a 13 określa dalsze rozszerzenie; na gitarze część składników się pomija.","steps":["Zapisz Cadd9 C–E–G–D i C9 C–E–G–B♭–D.","Zagraj Cadd9 x32030 i C7 x32310, słuchając różnicy.","Zapisz G13 jako G–B–D–F–A–C–E i wybierz szkielet G–B–F–E do ćwiczenia pojedynczymi nutami."],"example":"Cadd9 ≠ C9; 9 to 2 o oktawę wyżej.","criteria":["Wyjaśnij różnicę add9 i 9.","Zagraj składniki wybranego uproszczonego akordu 13."],"mistake":"Nie próbuj pomieścić siedmiu różnych dźwięków na sześciu strunach.","source":"chordmap","prerequisites":["ch-09-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-09-2","chapter":9,"order":9,"title":"Prowadzenie głosów bez dużych skoków","category":"Teoria","theory":"W harmonizacji ważny jest ruch poszczególnych linii. Wspólny dźwięk można zatrzymać, a pozostałe poprowadzić o sekundę.","steps":["Zagraj triady C, F i G z rozdziału 7 na górnych strunach.","Zapisz ruch każdej struny między C a F.","Ułóż cztery akordy z możliwie małym ruchem górnego głosu i zagraj wolno."],"example":"C–E–G → C–F–A: wspólne C, E→F, G→A.","criteria":["Wskaż wspólny dźwięk i dwa ruchome głosy.","Zagraj progresję bez przypadkowych przerw w melodii."],"mistake":"Najbliższy układ nie zawsze jest najlepszy: sprawdź wygodę i brzmienie.","source":"voicing","prerequisites":["deep-09-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-09-3","chapter":9,"order":10,"title":"Synkopa przez kreskę taktową","category":"Rytm","theory":"Dźwięk rozpoczęty przed mocną częścią i podtrzymany przez nią przesuwa odczuwany akcent. Wewnętrzny puls musi trwać mimo braku uderzenia na 1.","steps":["Licz ósemki przy 50 BPM.","Zagraj Em na „i” po 4 i pozwól mu brzmieć przez 1 następnego taktu.","Dodaj bas na 3 i powtórz cztery razy, cały czas licząc."],"example":"… 4 [i: akord] | 1 — 2 — 3 bas 4 …","criteria":["Utrzymaj osiem taktów bez dodatkowego uderzenia na 1.","Potrafisz wyklaskać wzór bez gitary."],"mistake":"Nie przesuwaj całego taktu razem z akcentem.","source":"meter","prerequisites":["deep-09-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-09-4","chapter":9,"order":11,"title":"Chord melody: najpierw szkielet","category":"Repertuar","theory":"Aranżację solo buduj od melodii i najważniejszych basów. Pełny akord na każdej nucie często utrudnia czytelność.","steps":["Wybierz osiem taktów znanej melodii i zagraj samą górną linię.","Dodaj tylko prymę akordu na początku taktu, zmieniając oktawę w razie potrzeby.","W dwóch miejscach dodaj tercję lub kwintę pod długą nutą melodii."],"example":"Melodia → basy na 1 → dwa wybrane wypełnienia.","criteria":["Zagraj osiem taktów rozpoznawalnej melodii z basem.","Żadne wypełnienie nie przerywa głównej frazy."],"mistake":"Nie próbuj od razu skopiować wielogłosowej aranżacji koncertowej.","source":"voicing","prerequisites":["deep-09-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-09-5","chapter":9,"order":12,"title":"Modalność przez dźwięk charakterystyczny","category":"Teoria","theory":"Tryb słyszysz względem centrum, nie od samego rozpoczęcia skali na innej nucie. Dorycki od a-moll naturalnego różni się F♯ zamiast F.","steps":["Zagraj bas A i porównaj frazy A–C–D–F–E oraz A–C–D–F♯–E.","Zakończ obie na A, aby zachować centrum.","Ułóż osiem taktów, w których F♯ jest świadomym kolorem, nie przypadkową pomyłką."],"example":"A dorycka: A B C D E F♯ G; centrum A.","criteria":["Rozróżnij oba warianty po porównaniu.","Pokaż charakterystyczną sekstę wielką A–F♯."],"mistake":"Nie nazywaj G-dur zagranej od A automatycznie dorycką muzyką bez centrum A.","source":"minor","prerequisites":["deep-09-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-09-6","chapter":9,"order":13,"title":"Własny wstęp i zakończenie","category":"Repertuar","theory":"Aranżacja staje się spójna, gdy wstęp przygotowuje tonację i puls, a zakończenie domyka formę. Nie musi to być popis techniczny.","steps":["Do wybranej piosenki dopisz dwutaktowy wstęp oparty na ostatnim akordzie i motywie melodii.","Dodaj zakończenie: dominanta, tonika i świadome wyciszenie.","Zagraj wstęp, jedną sekcję i zakończenie bez przerw."],"example":"Przygotowanie → temat → kadencja → cisza.","criteria":["Wstęp prowadzi do właściwego wejścia melodii.","Zakończenie jest zaplanowane i możliwe do powtórzenia."],"mistake":"Nie dodawaj efektownego intro, które jest trudniejsze niż cały utwór.","source":"cadences","prerequisites":["deep-09-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"ch-09-8","chapter":9,"order":14,"title":"Wyzwanie: Twoja aranżacja","category":"Repertuar","theory":"Połącz formę, melodię i akompaniament w spójną całość. Możesz wykorzystać melodię tradycyjną albo własny temat.","steps":["Wybierz temat i zapisz jego melodię oraz akordy.","Przygotuj minimum 16 taktów z basem, melodią i jednym kontrastem.","Zagraj od początku do końca w dobranym, stabilnym tempie."],"example":"Wymagane: temat + rozwinięcie + powrót + zakończenie","criteria":["Zagraj kompletną aranżację bez przerywania formy.","Uzasadnij dwa wybory harmoniczne lub rytmiczne."],"mistake":"Bogatsza faktura nie jest obowiązkowa w każdym takcie.","source":"classical","prerequisites":["deep-09-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-09","chapter":9,"order":15,"title":"Scena 9: Twoje brzmienie na sześciu strunach","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-09-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[15,40],"songChoices":["rep-blackbird","rep-dust","rep-greensleeves-arr","rep-tears","rep-house-arr"]},{"id":"side-09-1","chapter":9,"order":1,"title":"Akordy prowadzące w jazzie","category":"Teoria","theory":"W dominancie tercja i septyma często określają jej charakter. W G7 są to B i F, które mogą przejść do C i E.","steps":["Zagraj B i F razem: struna 3 próg 4 oraz struna 2 próg 6.","Przejdź do C i E: struna 3 próg 5 oraz struna 2 próg 5.","Dodaj bas G przed pierwszą parą i C przed drugą."],"example":"G7: B F → C: C E","criteria":["Usłysz i zagraj dwa półtonowe rozwiązania.","Nazwij tercję i septymę G7."],"mistake":"Nie dokładaj pełnych chwytów, zanim usłyszysz ruch dwóch głosów.","source":"theory","prerequisites":["ch-09-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-09-2","chapter":9,"order":2,"title":"Klasyczna etiuda: dwa głosy","category":"Repertuar","theory":"Autorska miniatura ćwiczy niezależną długość basu i melodii. Bas trwa cały takt, melodia porusza się ćwierćnutami.","steps":["W takcie 1 zagraj bas E oraz melodię E–G–F–E.","W takcie 2 zagraj bas A oraz melodię C–D–C–B na strunie 2: 1–3–1–0.","Powtórz cztery razy bez skracania basu."],"example":"Bas: | E — — — | A — — — |","criteria":["Zagraj osiem taktów z wybrzmiewającym basem i wyraźną melodią."],"mistake":"Nie tłum basu przy każdej zmianie dźwięku melodii.","source":"classical","prerequisites":["ch-09-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"branch-09-1","chapter":9,"order":3,"title":"Bossa: dwa takty rytmu","category":"Rytm","theory":"Bossa nova wymaga spokojnego, niezależnego basu. Ten wzór jest ćwiczeniem przygotowującym, nie jedynym poprawnym wzorem stylu.","steps":["Na Am7 graj bas na 1 i 3.","W takcie A dodaj akord na 1, „i” po 2 oraz 4.","W takcie B dodaj akord na „i” po 1, 3 oraz „i” po 4; ćwicz przy 45 BPM."],"example":"Bas zawsze 1 i 3; akordy zmieniają miejsca między taktami.","criteria":["Zagraj cztery dwutaktowe cykle bez przesuwania basu."],"mistake":"Nie próbuj od razu grać w tempie nagrania z pełnymi trudnymi chwytami.","source":"meter","prerequisites":["ch-09-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Jazz i bossa"},{"id":"branch-09-2","chapter":9,"order":4,"title":"Dominanta poboczna","category":"Teoria","theory":"Dominanta może na chwilę prowadzić do innego akordu niż tonika. W C-dur E7 prowadzi do Am, dlatego zawiera G♯ spoza skali C.","steps":["Porównaj C–Am–Dm–G z C–E7–Am–G.","Zaśpiewaj G♯→A przy przejściu E7–Am.","Dodaj taką dominantę do własnej czterotaktowej miniatury i porównaj wersje."],"example":"E7 = V/vi w C-dur; cel Am.","criteria":["Zagraj obie wersje i nazwij dodatkowe napięcie."],"mistake":"Nie dodawaj dominanty bez sprawdzenia, czy nie koliduje z melodią.","source":"cadences","prerequisites":["ch-09-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Jazz i bossa"},{"id":"branch-09-3","chapter":9,"order":5,"title":"Flażolet sztuczny: pojedynczy dźwięk","category":"Technika","theory":"Dotyk dwanaście progów powyżej skróconej struny daje flażolet oktawowy. Prawa ręka jednocześnie dotyka węzła i szarpie strunę.","steps":["Przytrzymaj F na 1/1.","Prawym wskazującym dotknij nad XIII progiem, a innym palcem szarp strunę.","Odsuń dotyk i porównaj z flażoletem pustej struny nad XII."],"example":"Dźwięk zatrzymany na progu n → dotyk nad n+12.","criteria":["Wydobądź trzy czyste flażolety F, bez ściskania prawej dłoni."],"mistake":"To opcjonalny kolor aranżacji; nie musi zastępować zwykłego dźwięku.","source":"technique","prerequisites":["ch-09-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Fingerstyle"},{"id":"ch-10-1","chapter":10,"order":1,"title":"Rozpracuj piosenkę ze słuchu","category":"Słuch","theory":"Samodzielne opracowanie łączy rozpoznanie pulsu, formy, melodii i basu. Wybierz utwór z prostą, czytelną harmonią.","steps":["Znajdź puls i podziel nagranie na sekcje.","Zaśpiewaj bas pierwszych czterech taktów i znajdź dźwięki.","Sprawdź akordy na gitarze, a następnie melodię jednego fragmentu."],"example":"Notatka: tempo · metrum · forma · bas · akordy · melodia","criteria":["Opracuj jedną pełną sekcję bez gotowych akordów.","Porównaj wykonanie z nagraniem i popraw rozbieżności."],"mistake":"Nie zgaduj akordów bez sprawdzenia basu i melodii.","source":"ear","prerequisites":["rep-09"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-10-2","chapter":10,"order":2,"title":"Analiza prowadzi do grania","category":"Teoria","theory":"Analiza pomaga przewidywać harmonię i świadomie frazować. Stopnie, kadencje i powtórzenia mają znaczenie wtedy, gdy potrafisz je usłyszeć.","steps":["Wybierz znaną piosenkę i zapisz akordy jako stopnie.","Zaznacz kadencje oraz miejsca napięcia.","Zagraj raz z akcentem na wszystkie pulsy, a potem z frazowaniem zgodnym z formą."],"example":"Dla C–Am–Dm–G7: I–vi–ii–V7","criteria":["Opisz tonację, formę i jedną kadencję utworu.","Pokaż zmianą wykonania, gdzie fraza się kończy."],"mistake":"Nie przypisuj funkcji bez sprawdzenia rzeczywistej tonacji sekcji.","source":"theory","prerequisites":["ch-10-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-10-3","chapter":10,"order":3,"title":"Dominanta w tonacji molowej","category":"Teoria","theory":"W A-moll akord E7 ma G♯, które prowadzi do A. A-moll harmoniczny podnosi siódmy stopień do G♯; nie trzeba używać tej skali nad każdym akordem.","steps":["Porównaj Em–Am i E7–Am.","Zagraj A–B–C–D–E–F–G♯–A.","Ułóż frazę nad Dm–E7–Am, używając G♯ przy E7."],"example":"Dm: D F A → E7: G♯ B D → Am: A C E","criteria":["Usłysz silniejszy powrót E7–Am.","Zastosuj G♯ w odpowiednim miejscu i rozwiąż na A."],"mistake":"Nie traktuj skali harmonicznej jako obowiązkowej na całe solo.","source":"theory","prerequisites":["ch-10-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-10-4","chapter":10,"order":4,"title":"Chromatyka z celem","category":"Improwizacja","theory":"Dźwięk chromatyczny może krótko prowadzić półtonem do składnika akordu. Jego rola zależy od czasu trwania i rozwiązania.","steps":["Nad C zagraj D♯–E i F–E jako dwie ósemki.","Porównaj długie zatrzymanie na D♯ z szybkim dojściem do E.","Wpleć jedno takie podejście w czterotaktowe solo."],"example":"Nad C: D♯ → E; nad Am: G♯ → A","criteria":["Zagraj trzy frazy z kontrolowanym podejściem półtonowym.","Nazwij cel oraz moment rozwiązania."],"mistake":"Nie dodawaj przypadkowych chromatycznych dźwięków bez słyszenia celu.","source":"intermediate","prerequisites":["ch-10-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-10-5","chapter":10,"order":5,"title":"Napisz własny utwór","category":"Improwizacja","theory":"Kompozycja rozwija i porządkuje pomysły. Ograniczenia pomagają: jedna tonacja, krótki motyw i czytelna forma wystarczą.","steps":["Wybierz tonację i cztery akordy.","Ułóż motyw, wariację oraz kontrastową odpowiedź.","Zapisz co najmniej 16 taktów, tytuł i sposób zakończenia."],"example":"Szkielet: intro 2 takty + A 8 taktów + B 4 takty + zakończenie 2 takty","criteria":["Zagraj utwór dwa razy w tej samej formie.","Zapis pozwala odtworzyć go następnego dnia."],"mistake":"Nie poprawiaj pierwszego taktu bez końca; najpierw dokończ całość.","source":"intermediate","prerequisites":["ch-10-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-10-6","chapter":10,"order":6,"title":"Interpretacja i artykulacja","category":"Technika","theory":"Te same nuty mogą brzmieć inaczej dzięki dynamice, długości i kierunkowi frazy. Zaplanuj zmiany zamiast wykonywać je przypadkowo.","steps":["Wybierz osiem taktów repertuaru.","Zaznacz szczyt frazy, dwa miejsca wyciszenia i jeden kontrast artykulacji.","Zagraj wersję neutralną i zaplanowaną, porównując efekt."],"example":"Plan frazy: spokojnie → narastanie → szczyt → wyciszenie","criteria":["Dwie wersje są słyszalnie różne.","Zmiany ekspresji nie destabilizują rytmu."],"mistake":"Nie zastępuj ekspresji przypadkowym zwalnianiem w trudnych miejscach.","source":"classical","prerequisites":["ch-10-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"ch-10-7","chapter":10,"order":7,"title":"Próba występu","category":"Repertuar","theory":"Występ ćwiczymy osobno od naprawiania szczegółów. Celem próby jest dokończenie programu i odzyskanie orientacji po potknięciu.","steps":["Wybierz trzy pozycje: utwór, własną aranżację i improwizację.","Nastrój gitarę i zagraj cały zestaw bez zatrzymywania się na poprawki.","Po próbie zanotuj dwa fragmenty do osobnego ćwiczenia."],"example":"Przygotowanie → utwór → aranżacja → improwizacja → notatka","criteria":["Dokończ wszystkie trzy części.","Po błędzie odzyskaj puls lub wróć w ustalonym punkcie formy."],"mistake":"Nie zamieniaj próby występu w wielokrotne poprawianie jednego taktu.","source":"practice","prerequisites":["ch-10-6"],"optional":false,"challenge":false,"minutes":5,"sessions":[2,4]},{"id":"deep-10-1","chapter":10,"order":8,"title":"Analiza przed pierwszą próbą","category":"Teoria","theory":"Analiza powinna ułatwiać granie. Tonacja, forma, kadencje i zmiany pozycji mówią, gdzie poświęcić czas.","steps":["Wybierz utwór finałowy i przejrzyj lekcję oraz dostępny zapis.","Zanotuj tonację, metrum, sekcje i trzy trudne miejsca.","Dla każdego miejsca zaplanuj jedno krótkie ćwiczenie, zamiast powtarzać całość."],"example":"Problem: zmiana pozycji → ćwiczenie: ostatnia nuta przed zmianą + pierwsza po zmianie.","criteria":["Masz mapę utworu i trzy konkretne ćwiczenia.","Potrafisz wskazać miejsce największego napięcia harmonicznego."],"mistake":"Analiza nie jest przepisywaniem wszystkich nazw nut do notatki.","source":"practice","prerequisites":["ch-10-7"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-10-2","chapter":10,"order":9,"title":"Pamięć w punktach orientacyjnych","category":"Technika","theory":"Pamięć wyłącznie ruchowa bywa krucha. Osobne punkty startowe pozwalają wrócić do muzyki po pomyłce.","steps":["Wybierz początki trzech fraz w utworze.","Zagraj każdą od razu, bez poprzedzającego fragmentu.","W następnej sesji losuj kolejność i nazwij akord lub tonację miejsca startu."],"example":"Start A → start C → start B, bez rozbiegu.","criteria":["Rozpocznij od trzech punktów w dwóch różnych dniach.","Po celowej przerwie wróć od najbliższej frazy."],"mistake":"Nie ćwicz pamięci wyłącznie przez odtwarzanie od pierwszego taktu.","source":"practice","prerequisites":["deep-10-1"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-10-3","chapter":10,"order":10,"title":"Interpretacja: plan frazy i rubato","category":"Repertuar","theory":"Rubato jest świadomą elastycznością czasu. Najpierw potrzebujesz stabilnego pulsu, aby odróżnić interpretację od potknięcia technicznego.","steps":["Zagraj frazę z metronomem i zaplanuj szczyt dynamiki.","Bez metronomu delikatnie poszerz zakończenie, utrzymując ciągłość melodii.","Powtórz tę samą interpretację, a następnie porównaj z wersją równą."],"example":"Początek spokojny → kierunek do szczytu → odprężenie.","criteria":["Potrafisz powtórzyć ten sam plan frazy.","Zwolnienie nie pojawia się wyłącznie w trudnym technicznie miejscu."],"mistake":"Nie maskuj każdej pomyłki słowem rubato.","source":"roman","prerequisites":["deep-10-2"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-10-4","chapter":10,"order":11,"title":"Kompozycja z ograniczeniami","category":"Improwizacja","theory":"Ograniczona forma ułatwia ukończenie pomysłu. Kontrast nie musi oznaczać nowej techniki: może zmienić się rytm lub rejestr.","steps":["Napisz temat A ośmiu taktów z jednym motywem.","Dopisz B ośmiu taktów, zmieniając rytm lub harmonię, a potem wróć do A.","Zapisz melodię i akordy na tyle dokładnie, by odtworzyć utwór jutro."],"example":"A (8) – B (8) – A (8); zakończenie na wybranej tonice.","criteria":["Zagraj całą miniaturę 24 taktów.","Odtwórz ją następnego dnia bez ponownego komponowania."],"mistake":"Nie poprawiaj bez końca pierwszych dwóch taktów kosztem ukończenia formy.","source":"cadences","prerequisites":["deep-10-3"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-10-5","chapter":10,"order":12,"title":"Próba generalna bez zatrzymań","category":"Repertuar","theory":"Próba występu obejmuje także wejście, oddech, ciszę między utworami i reakcję na pomyłkę. To osobna umiejętność.","steps":["Przygotuj trzy pozycje: utwór, własną aranżację i krótką improwizację.","Nastrój gitarę, ustaw kolejność i wykonaj wszystko w jednej próbie.","Po zakończeniu zapisz tylko trzy najważniejsze poprawki, potem ćwicz je osobno."],"example":"Wejście → utwór → cisza → aranżacja → improwizacja → zakończenie.","criteria":["Wykonaj próbę od początku do końca bez restartu.","Następna próba zawiera co najmniej jedną konkretną poprawę."],"mistake":"Nie oceniaj całego występu na podstawie jednego zabrzęczenia.","source":"practice","prerequisites":["deep-10-4"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"deep-10-6","chapter":10,"order":13,"title":"Twój następny cykl nauki","category":"Teoria","theory":"Samodzielność oznacza umiejętność wyboru problemu, metody i sprawdzianu. Kolejny etap powinien wynikać z muzyki, którą chcesz grać.","steps":["Wybierz dwa utwory na następne cztery tygodnie i jedną odnogę.","Rozpisz tydzień: trzy sesje pracy, jedna powtórka, jedna próba całości.","Ustal mierzalne kryterium, np. pełna sekcja z równym basem, i sprawdź je po tygodniu."],"example":"Utwór → brakująca umiejętność → małe ćwiczenie → sprawdzian → korekta planu.","criteria":["Masz plan tygodnia i kryterium dla obu utworów.","Potrafisz zmniejszyć zakres zadania, gdy okazuje się za trudne."],"mistake":"Brak szybkiego zaliczenia nie oznacza braku nauki. Dopasuj wielkość kroku.","source":"practice","prerequisites":["deep-10-5"],"optional":false,"challenge":false,"minutes":5,"sessions":[4,8]},{"id":"ch-10-8","chapter":10,"order":14,"title":"Wyzwanie: Twój miniwystęp","category":"Repertuar","theory":"To podsumowanie samodzielności: potrafisz przygotować muzykę, zagrać ją i wskazać dalszy kierunek rozwoju. Nie jest to formalny egzamin ani koniec nauki.","steps":["Przygotuj 5–10 minut programu: piosenka, aranżacja fingerstyle i improwizacja.","Zagraj całość dla siebie lub wybranej osoby, zachowując formę.","Zapisz trzy mocne strony i jeden konkretny cel na kolejny miesiąc."],"example":"Program: repertuar + własna aranżacja + improwizacja nad znaną harmonią","criteria":["Dokończ wszystkie trzy części w kontrolowanym tempie.","Improwizacja reaguje na harmonię, a aranżacja eksponuje melodię.","Zapisz następny cel z mierzalnym kryterium."],"mistake":"Nie utożsamiaj pojedynczej pomyłki z nieudanym występem.","source":"classical","prerequisites":["deep-10-6"],"optional":false,"challenge":true,"minutes":7,"sessions":[3,6]},{"id":"rep-10","chapter":10,"order":15,"title":"Scena 10: Utwór na finałowy występ","category":"Repertuar","theory":"Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.","steps":["Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.","Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.","Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny."],"example":"Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.","criteria":["Wykonałem dokładnie wskazany zakres wybranego utworu.","Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem."],"mistake":"Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.","source":"marty","prerequisites":["ch-10-8"],"optional":false,"challenge":true,"minutes":7,"sessions":[20,50],"songChoices":["rep-lagrima","rep-romanza","rep-bourree"]},{"id":"side-10-1","chapter":10,"order":1,"title":"Mapa dalszej specjalizacji","category":"Teoria","theory":"Po wspólnym fundamencie rozwój zależy od repertuaru i celu. Wybierz jedną odnogę na najbliższe tygodnie.","steps":["Wybierz blues, fingerstyle, jazz/bossa lub klasykę.","Wskaż dwa utwory oraz brakującą umiejętność.","Zapisz tygodniowy plan trzech krótkich ćwiczeń."],"example":"Cel → utwór → umiejętność → ćwiczenie → sprawdzian","criteria":["Zapisz konkretny cel i kryterium, po którym poznasz postęp."],"mistake":"Nie planuj jednocześnie wszystkich stylów.","source":"practice","prerequisites":["ch-10-2"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"side-10-2","chapter":10,"order":2,"title":"Własna sesja 18 minut","category":"Technika","theory":"Samodzielny muzyk potrafi dopasować ćwiczenie do problemu. Nadal warto łączyć powtórkę, nowe wyzwanie i granie muzyki.","steps":["Wybierz trudne dwa takty z repertuaru.","Zaplanuj 2 min przygotowania, 4 powtórki, 5 pracy nad problemem i 7 grania.","Wykonaj sesję i zapisz, co konkretnie się poprawiło."],"example":"2 + 4 + 5 + 7 = 18 minut","criteria":["Wykonaj sesję i porównaj trudny fragment przed oraz po."],"mistake":"Nie zastępuj ćwiczenia samego problemu ciągłym graniem utworu od początku.","source":"practice","prerequisites":["ch-10-5"],"optional":true,"challenge":false,"minutes":5,"sessions":[2,5],"branch":"Dodatkowa praktyka"},{"id":"branch-10-1","chapter":10,"order":3,"title":"Dwa głosy Bacha osobno","category":"Repertuar","theory":"W kontrapunkcie bas jest drugą melodią. Ćwiczenie go osobno pozwala usłyszeć kierunek niezależny od góry.","steps":["Wybierz cztery takty Bourrée z darmowej lekcji.","Zagraj sam górny głos, następnie sam bas, zachowując zapisane długości.","Połącz je w wolnym tempie, wyróżniając raz górę, raz dół."],"example":"Głos górny → dolny → razem z różnym balansem.","criteria":["Wykonaj oba głosy niezależnie i połącz cztery takty."],"mistake":"Nie skracaj każdej nuty basu do chwili następnego dźwięku melodii.","source":"bach","prerequisites":["ch-10-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Klasyka"},{"id":"branch-10-2","chapter":10,"order":4,"title":"Własna aranżacja w dwóch gęstościach","category":"Repertuar","theory":"Dobra aranżacja może mieć wersję prostą i bogatszą. Obie muszą zachować melodię oraz formę.","steps":["Wybierz osiem taktów własnego chord melody.","Zagraj wersję sam bas i melodia.","Dodaj dwa ozdobniki oraz wypełnienia tylko pod długimi nutami i porównaj."],"example":"Wersja A: dwa głosy; wersja B: te same głosy plus wybrane wypełnienia.","criteria":["Obie wersje są rozpoznawalne i mają ten sam puls."],"mistake":"Więcej nut nie zawsze daje lepszy rezultat muzyczny.","source":"voicing","prerequisites":["ch-10-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Fingerstyle"},{"id":"branch-10-3","chapter":10,"order":5,"title":"Reharmonizacja pod melodią","category":"Teoria","theory":"Nowy akord powinien współpracować z ważnym dźwiękiem melodii. Najpierw sprawdź ten dźwięk, dopiero potem efektowną nazwę chwytu.","steps":["Wybierz frazę kończącą się na E nad C.","Porównaj C, Am7 i Cmaj7 pod tym samym E.","Zagraj po dwa takty każdej wersji i zapisz, jak zmienił się kierunek harmoniczny."],"example":"E nad C = tercja; E nad Am7 = kwinta.","criteria":["Zagraj trzy harmonizacje tej samej frazy i nazwij rolę E."],"mistake":"Nie zmieniaj akordów tak często, by melodia straciła punkt odniesienia.","source":"voicing","prerequisites":["ch-10-7"],"optional":true,"challenge":false,"minutes":5,"sessions":[4,8],"branch":"Jazz i bossa"}],"songs":[{"id":"rep-ode-melody","title":"Oda do radości","artist":"Ludwig van Beethoven","chapter":1,"kind":"Piosenka","version":"Sama melodia · pozycja otwarta, bez akordów","teacher":"GuitarWithBrett","nylon":"Graj pojedyncze dźwięki i–m. Pomijaj dodatkowe warianty z akompaniamentem.","checkpoint":1,"language":"EN","url":"https://www.youtube.com/watch?v=iFDPa2rADfo","requirements":["ch-01-8"],"example":"Zacznij od pierwszej frazy w C-dur. Podziel melodię na odcinki po cztery takty i połącz je dopiero, gdy pamiętasz rytm.","practice":["Zacznij od pierwszej frazy w C-dur. Podziel melodię na odcinki po cztery takty i połącz je dopiero, gdy pamiętasz rytm.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj całą melodię z lekcji przy 50–60 BPM.","Powtórz ją w innym dniu, nie zatrzymując pulsu po pomyłce."],"sessions":[5,12]},{"id":"rep-twinkle","title":"Twinkle, Twinkle, Little Star","artist":"Melodia tradycyjna","chapter":1,"kind":"Piosenka","version":"Melodia jednogłosowa · bez fingerstyle z basem","teacher":"GuitarNick","nylon":"Wybierz wygodne palcowanie bez rozciągania dłoni. Tonacja z filmu nie musi pasować do Twojego głosu.","checkpoint":1,"language":"Demonstracja / zapis","url":"https://www.youtube.com/watch?v=L9Z6OONa84g","requirements":["ch-01-8"],"example":"Zaśpiewaj trzy części melodii. Naucz się osobno części początkowej i środkowej; ostatnia powtarza początek.","practice":["Zaśpiewaj trzy części melodii. Naucz się osobno części początkowej i środkowej; ostatnia powtarza początek.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj trzy części A–B–A w równym tempie 50–60 BPM.","Długie dźwięki trwają dwa pulsy; nie skracaj zakończeń fraz."],"sessions":[5,12]},{"id":"rep-seven","title":"Seven Nation Army","artist":"The White Stripes","chapter":1,"kind":"Riff","version":"Główny riff jednogłosowo · fragment, nie cała piosenka","teacher":"Marty Music","nylon":"Graj kciukiem lub i–m. Nie potrzebujesz efektu oktawowego, power chordów ani brzmienia elektrycznego.","checkpoint":1,"language":"EN","url":"https://www.youtube.com/watch?v=fLCXZs6SWFQ","requirements":["ch-01-8"],"example":"W filmie wybierz sam główny riff. Ucz się jego pierwszej i drugiej połowy osobno, potem łącz z pauzą na końcu.","practice":["W filmie wybierz sam główny riff. Ucz się jego pierwszej i drugiej połowy osobno, potem łącz z pauzą na końcu.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Powtórz riff cztery razy bez zatrzymania przy około 50–60 BPM.","Zachowaj charakterystyczne długie i krótkie dźwięki."],"sessions":[5,12]},{"id":"song-04","title":"Three Little Birds","artist":"Bob Marley & The Wailers","chapter":2,"kind":"Piosenka","version":"A–D–E · spokojny akompaniament, jedno uderzenie na puls","teacher":"Marty Music","nylon":"Uderzaj struny miękko palcem. Oryginalny reggae offbeat zostaw na później.","checkpoint":2,"language":"EN","url":"https://www.youtube.com/watch?v=qCCJ-CVNND4","requirements":["ch-02-8"],"example":"Przećwicz osobno A–D i D–E. Rozpisz kolejność sekcji z lekcji i utrzymaj proste ćwierćnuty przez zwrotkę oraz refren.","practice":["Przećwicz osobno A–D i D–E. Rozpisz kolejność sekcji z lekcji i utrzymaj proste ćwierćnuty przez zwrotkę oraz refren.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj zwrotkę i refren po dwa razy przy 60 BPM.","Zmieniaj akord na właściwym pulsie bez poprawiania chwytu w połowie taktu."],"sessions":[5,12]},{"id":"rep-horse","title":"A Horse with No Name","artist":"America","chapter":2,"kind":"Piosenka","version":"Dwa chwyty z lekcji · równy akompaniament","teacher":"Marty Music","nylon":"Nie kopiuj siły kostkowania. Miękki palec wskazujący wystarczy na nylonowych strunach.","checkpoint":2,"language":"EN","url":"https://www.youtube.com/watch?v=qO3yqu96q28","requirements":["ch-02-8"],"example":"Najpierw opanuj oba pokazane chwyty. Graj cały cykl ćwierćnutami, potem zastosuj jeden podstawowy rytm z lekcji.","practice":["Najpierw opanuj oba pokazane chwyty. Graj cały cykl ćwierćnutami, potem zastosuj jeden podstawowy rytm z lekcji.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Utrzymaj co najmniej 16 taktów przy 60–70 BPM.","Zagraj dwa kolejne przebiegi bez zatrzymania na zmianie."],"sessions":[5,12]},{"id":"song-09","title":"Knockin’ on Heaven’s Door","artist":"Bob Dylan","chapter":2,"kind":"Piosenka","version":"G–D–Am–C · akompaniament w wolnym tempie","teacher":"Marty Music","nylon":"Bez solówek i podciągnięć z wersji Guns N’ Roses. Na tym etapie liczą się akordy i czas.","checkpoint":2,"language":"EN","url":"https://www.youtube.com/watch?v=mMnla7_Ipr4","requirements":["ch-02-8"],"example":"Oddziel cykl kończący się Am od cyklu kończącego się C. Naucz się kolejności, dopiero potem dokładaj ósemki.","practice":["Oddziel cykl kończący się Am od cyklu kończącego się C. Naucz się kolejności, dopiero potem dokładaj ósemki.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj zwrotkę i refren bez mylenia Am z C przy 55–65 BPM.","Utrzymaj formę, nawet jeśli pojedyncza struna zabrzęczy."],"sessions":[5,12]},{"id":"song-10","title":"Stand By Me","artist":"Ben E. King","chapter":3,"kind":"Piosenka","version":"Łatwa wersja G–Em–C–D · pełny cykl rytmiczny","teacher":"JustinGuitar","nylon":"W tym wariancie nie musisz jednocześnie grać linii basu i akordów.","checkpoint":3,"language":"EN","url":"https://www.youtube.com/watch?v=KlHFye6_Icc","requirements":["ch-03-8"],"example":"Połącz G–Em oraz C–D, a następnie całą pętlę. Rozróżnij czas trwania każdego akordu w wersji nauczyciela.","practice":["Połącz G–Em oraz C–D, a następnie całą pętlę. Rozróżnij czas trwania każdego akordu w wersji nauczyciela.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj przynajmniej cztery pełne cykle z jednym rytmem przy 60–75 BPM.","Zakończ świadomie na tonice; nie urywaj przypadkowo w połowie cyklu."],"sessions":[5,12]},{"id":"rep-come","title":"Come As You Are","artist":"Nirvana","chapter":3,"kind":"Riff","version":"Główny riff · w standardowym stroju EADGBE","teacher":"Marty Music","nylon":"Pozostajemy w standardowym stroju; oryginalne nagranie może brzmieć w innej wysokości. Nie przestrajaj gitary tylko dla tego zadania.","checkpoint":3,"language":"EN","url":"https://www.youtube.com/watch?v=3UV1CtIUOmU","requirements":["ch-03-8"],"example":"Wydziel zmianę między dwiema strunami. Zagraj ją bardzo wolno, a potem dołącz resztę riffu z lekcji.","practice":["Wydziel zmianę między dwiema strunami. Zagraj ją bardzo wolno, a potem dołącz resztę riffu z lekcji.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj osiem powtórzeń przy 60–75 BPM, bez przypadkowego nakładania basów.","Potrafisz wejść ponownie po jednym takcie ciszy."],"sessions":[5,12]},{"id":"rep-wish-intro","title":"Wish You Were Here","artist":"Pink Floyd","chapter":3,"kind":"Riff","version":"Pierwsza fraza instrumentalnego wstępu · bez solówki","teacher":"Marty Music","nylon":"Kostkę możesz zastąpić kciukiem i palcem wskazującym. Dalsze ozdobniki są na później.","checkpoint":3,"language":"EN","url":"https://www.youtube.com/watch?v=IzxMeQgtyYE","requirements":["ch-03-8"],"example":"Z lekcji wybierz pierwszą frazę wstępu. Oddziel pojedyncze dźwięki od lekkiego uderzenia akordu i ćwicz przejście między nimi.","practice":["Z lekcji wybierz pierwszą frazę wstępu. Oddziel pojedyncze dźwięki od lekkiego uderzenia akordu i ćwicz przejście między nimi.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj pierwszą frazę cztery razy w równym, własnym tempie.","Dźwięki melodii są słyszalne ponad akordowym uderzeniem."],"sessions":[5,12]},{"id":"rep-greensleeves-melody","title":"Greensleeves","artist":"Melodia tradycyjna","chapter":4,"kind":"Piosenka","version":"Sama melodia z darmowego Method Book Vol. 1","teacher":"Bradford Werner","nylon":"To melodia jednogłosowa. Nie wymaga jeszcze trudnej aranżacji lutniowej ani barré.","checkpoint":4,"language":"EN","url":"https://www.youtube.com/watch?v=8obTT2lpU4Q","requirements":["ch-04-8"],"example":"Przejdź w filmie do części Greensleeves. Zapisz początek melodii nazwami dźwięków i znajdź najbliższe półtony.","practice":["Przejdź w filmie do części Greensleeves. Zapisz początek melodii nazwami dźwięków i znajdź najbliższe półtony.","W następnej sesji zacznij od najtrudniejszego połączenia, nie od początku utworu. Zagraj je trzy razy spokojnie i dodaj po jednym takcie z każdej strony.","Zagraj ustalony zakres bez zatrzymania. Zapisz tempo i jeden konkretny problem. W innym dniu powtórz próbę bez wcześniejszego odtwarzania filmu."],"criteria":["Zagraj obie części melodii z zachowaniem metrum.","Nazwij pięć użytych dźwięków i pokaż jeden skok oraz jeden ruch sekundowy."],"sessions":[10,25]},{"id":"rep-birthday","title":"Happy Birthday","artist":"Tradycyjny repertuar okazjonalny","chapter":4,"kind":"Piosenka","